# Load the data
df = pd.read_csv(StringIO(data.strip()), delimiter=",", quotechar='"', engine='python', on_bad_lines='skip')

# --- Step 1: Examining Historical Data ---
leadership_df = df[df['Category'] == 'Leadership Decisions and Ideological Analysis']
def extract_ideology_score(value):
    import re
    match = re.search(r'Ideology Score: ([+-]?\d*\.?\d+)?\s*(Right|Left)?|Total: ([+-]?\d*\.?\d+)\s*(Right|Left)', str(value))
    if match:
        if match.group(1) and match.group(2):  # For detailed scores like "+0.6 Right"
            return float(match.group(1)), match.group(2)
        elif match.group(3) and match.group(4):  # For totals like "Total: -1.8 Left"
            return float(match.group(3)), match.group(4)
    return None, None

def extract_policy_keywords(value):
    import re
    match = re.search(r'Policy Keywords: (.+?);', str(value))
    return match.group(1) if match else None

leaders_df = leadership_df[leadership_df['Value'].str.contains('Entity Type: Leader', na=False)].copy()
leaders_df['Leader'] = leaders_df['Field'].str.split(' - ').str[0]
leaders_df['Ideology_Score'], leaders_df['Ideology_Direction'] = zip(*leaders_df['Value'].apply(extract_ideology_score))
leaders_df['Policy_Keywords'] = leaders_df['Value'].apply(extract_policy_keywords)

def categorize_ideology(score, direction):
    if score is None or direction is None:
        return 'Unknown'
    score = float(score)
    if score > 0 and direction == 'Right':
        return 'Right'
    elif score < 0 and direction == 'Left':
        return 'Left'
    elif score == 0:
        return 'Centrist'
    return 'Unknown'

leaders_df['Ideology_Category'] = leaders_df.apply(lambda row: categorize_ideology(row['Ideology_Score'], row['Ideology_Direction']), axis=1)
result_df = leaders_df[['Event', 'Leader', 'Ideology_Score', 'Ideology_Category', 'Policy_Keywords']]
print("Step 1: Leadership Ideological Analysis Table:")
print(result_df)

# --- Step 2: Repeated and Sequential Games ---
game_df = df[df['Category'] == 'Application of Behavioral Game Theory']
def extract_numeric(value):
    import re
    match = re.search(r'(\d+)', str(value))
    return float(match.group(1)) if match else None

concessions = game_df[game_df['Field'] == 'Concession_Size'].copy()
escalations = game_df[game_df['Field'] == 'Escalation_Level'].copy()
concessions['Concession_Size'] = concessions['Value'].apply(extract_numeric)
escalations['Escalation_Level'] = escalations['Value'].apply(extract_numeric)
game_metrics = pd.merge(concessions[['Event', 'Concession_Size']],
                        escalations[['Event', 'Escalation_Level']],
                        on='Event',
                        how='outer')

plt.figure(figsize=(10, 6))
plt.plot(game_metrics['Event'], game_metrics['Concession_Size'], label='Concession Size', marker='o', color='blue')
plt.plot(game_metrics['Event'], game_metrics['Escalation_Level'], label='Escalation Level', marker='o', color='red')
plt.xlabel('Events')
plt.ylabel('Values (0-10 Scale)')
plt.title('Step 2: Repeated Games - Concessions and Escalation Trends')
plt.legend()
plt.xticks(rotation=45)
plt.grid(True)
plt.tight_layout()
plt.show()

print("\nStep 2: Repeated Games Analysis Table:")
print(game_metrics)

decision_nodes_2023 = game_df[(game_df['Event'] == '2023 Escalation') & (game_df['Field'] == 'Decision Node Details')]
print("\nStep 2: Sequential Games - Decision Nodes for 2023 Escalation:")
print(decision_nodes_2023['Value'].values[0])
sequential_nodes = game_df[(game_df['Event'] == '2023 Escalation') & (game_df['Field'] == 'Sequential Decision Tree')]['Value'].values[0]
print("\nSequential Game Breakdown:")
for i, node in enumerate(sequential_nodes.split(' → '), 1):
    print(f"Step {i}: {node}")

# --- Step 3: Game Trees, Payoff Matrices, and Scenario Analysis ---
dot = Digraph()
dot.node('A', 'Hamas Attack')
dot.node('B', 'Israel Response')
dot.node('C', 'Mediation Efforts')
dot.node('D', 'Partial Ceasefires')
dot.node('E', 'Continued Conflict')
dot.edges(['AB', 'BC', 'BD', 'BE'])
dot.render('game_tree_2023', format='png')
print("\nStep 3: Game Tree for 2023 Escalation saved as 'game_tree_2023.png' in Files tab.")

payoff_matrix = {
    'Israel_Cooperate': {'Palestine_Cooperate': (50, 50), 'Palestine_Confront': (10, 70)},
    'Israel_Confront': {'Palestine_Cooperate': (70, 10), 'Palestine_Confront': (20, 20)}
}
print("\nStep 3: Payoff Matrix (Israel, Palestine):")
for row, cols in payoff_matrix.items():
    print(row)
    for col, payoff in cols.items():
        print(f"  {col}: {payoff}")

avg_concession = game_metrics['Concession_Size'].mean()
print(f"\nStep 3: Scenario Analysis - Average Concession Size: {avg_concession:.2f}")
if avg_concession > 5:
    print("Likely Outcome: Economic growth, SDG progress (Cooperative Equilibrium)")
else:
    print("Likely Outcome: GDP decline, developmental setbacks (Confrontational Equilibrium)")

