# Load data
df = pd.read_csv(StringIO(data.strip()), delimiter=",", quotechar='"', engine='python', on_bad_lines='skip')

# --- Enhanced Repeated Games Graph with Trust Level and Bounded Rationality ---
game_df = df[df['Category'].isin(['Application of Behavioral Game Theory', 'Behavioral Factors'])]

def extract_numeric(value):
    import re
    match = re.search(r'(\d+)', str(value))
    return float(match.group(1)) if match else None

# Extract Concession_Size, Escalation_Level, Trust_Level, and Bounded_Rationality-impact
concessions = game_df[game_df['Field'] == 'Concession_Size'].copy()
escalations = game_df[game_df['Field'] == 'Escalation_Level'].copy()
trusts = game_df[game_df['Field'] == 'Trust Level'].copy()
bounded_rationality = game_df[game_df['Field'] == 'Bounded Rationality Impact'].copy()

concessions['Concession_Size'] = concessions['Value'].apply(extract_numeric)
escalations['Escalation_Level'] = escalations['Value'].apply(extract_numeric)
trusts['Trust_Level'] = trusts['Value'].apply(extract_numeric)
bounded_rationality['Bounded_Rationality'] = bounded_rationality['Value'].map({'Low': 1, 'Moderate': 2, 'High': 3})

# Merge data into a single DataFrame
game_metrics = pd.merge(concessions[['Event', 'Concession_Size']], escalations[['Event', 'Escalation_Level']], on='Event', how='outer')
game_metrics = pd.merge(game_metrics, trusts[['Event', 'Trust_Level']], on='Event', how='outer')
game_metrics = pd.merge(game_metrics, bounded_rationality[['Event', 'Bounded_Rationality']], on='Event', how='outer')

# Plotting the enhanced repeated games graph
fig, ax1 = plt.subplots(figsize=(12, 7))
ax1.plot(game_metrics['Event'], game_metrics['Concession_Size'], label='Concession Size', marker='o', color='#1f77b4', linewidth=2)
ax1.plot(game_metrics['Event'], game_metrics['Escalation_Level'], label='Escalation Level', marker='o', color='#d62728', linewidth=2)
ax1.plot(game_metrics['Event'], game_metrics['Trust_Level'], label='Trust Level', marker='o', color='#2ca02c', linewidth=2)
ax1.set_xlabel('Critical Junctures', fontsize=12)
ax1.set_ylabel('Level (0-10)', fontsize=12)
ax1.set_title('Repeated Games in Israel-Palestine: Cooperation, Conflict, and Trust (1978–2023)', fontsize=16, pad=15)
ax1.grid(True, linestyle='--', alpha=0.5)
ax1.set_xticks(game_metrics['Event'])
ax1.set_xticklabels(game_metrics['Event'], rotation=45, fontsize=10)
ax1.set_yticks(range(0, 11))

# Annotations for primary axis
for i, (x, y) in enumerate(zip(game_metrics['Event'], game_metrics['Concession_Size'])):
    ax1.text(x, y + 0.3, f'{y:.1f}', ha='center', fontsize=10, color='#1f77b4')
for i, (x, y) in enumerate(zip(game_metrics['Event'], game_metrics['Escalation_Level'])):
    ax1.text(x, y + 0.3, f'{y:.1f}', ha='center', fontsize=10, color='#d62728')
for i, (x, y) in enumerate(zip(game_metrics['Event'], game_metrics['Trust_Level'])):
    ax1.text(x, y + 0.3, f'{y:.1f}', ha='center', fontsize=10, color='#2ca02c')

# Secondary axis for Bounded Rationality
ax2 = ax1.twinx()
ax2.plot(game_metrics['Event'], game_metrics['Bounded_Rationality'], label='Bounded Rationality', marker='o', color='#9467bd', linewidth=2)
ax2.set_ylabel('Bounded Rationality Impact (1=Low, 3=High)', fontsize=12)
ax2.set_yticks([1, 2, 3])
ax2.set_yticklabels(['Low', 'Moderate', 'High'], fontsize=10)
for i, (x, y) in enumerate(zip(game_metrics['Event'], game_metrics['Bounded_Rationality'])):
    ax2.text(x, y + 0.1, f'{int(y)}', ha='center', fontsize=10, color='#9467bd')

# Combine legends
lines1, labels1 = ax1.get_legend_handles_labels()
lines2, labels2 = ax2.get_legend_handles_labels()
ax1.legend(lines1 + lines2, labels1 + labels2, loc='upper left', fontsize=10)
plt.tight_layout()
plt.show()

# --- Public Pressure Bar Chart for 2023 Escalation ---
pressure_df = df[(df['Event'] == '2023 Escalation') &
                 (df['Category'] == 'Leadership Decisions and Ideological Analysis') &
                 (df['Field'].str.contains('Public Pressure Score'))].copy()
pressure_df['Leader'] = pressure_df['Field'].apply(lambda x: x.split(' - ')[0])
pressure_df['Public_Pressure_Score'] = pressure_df['Value'].astype(float)

plt.figure(figsize=(10, 6))
sns.barplot(x='Leader', y='Public_Pressure_Score', data=pressure_df, palette='viridis')
plt.title('Public Pressure Scores for Leaders in 2023 Escalation', fontsize=16)
plt.xlabel('Leader', fontsize=12)
plt.ylabel('Public Pressure Score (0-10)', fontsize=12)
plt.xticks(rotation=45, ha='right', fontsize=10)
plt.tight_layout()
plt.show()

# --- Enhanced Game Tree for 2023 Escalation ---
dot = Digraph(comment='2023 Escalation Sequential Game', graph_attr={'rankdir': 'TB', 'splines': 'ortho'})
dot.attr('node', shape='box', style='filled', fillcolor='#f0f8ff', fontname='Arial')
dot.attr('edge', arrowhead='vee', fontname='Arial')
dot.node('A', 'Hamas Attack\n(Oct 7, 2023)', fillcolor='#ffcccc')
dot.node('B', 'Israel Response\n(Netanyahu)', fillcolor='#ff9999')
dot.node('C', 'Mediation Efforts\n(Biden, Blinken)', fillcolor='#cce5ff')
dot.node('D', 'Partial Ceasefires\n(Temporary Calm)', fillcolor='#99ccff')
dot.node('E', 'Continued Conflict\n(Economic Loss)', fillcolor='#ff6666')
dot.edges(['AB', 'BC', 'BD', 'BE'])
dot.render('enhanced_game_tree_2023', format='png', cleanup=False)
display(Image(filename='enhanced_game_tree_2023.png'))
print("Enhanced Game Tree displayed above.")

# --- Enhanced Payoff Matrix Heatmap ---
payoff_matrix = {
    'Israel_Cooperate': {'Palestine_Cooperate': (50, 50), 'Palestine_Confront': (10, 70)},
    'Israel_Confront': {'Palestine_Cooperate': (70, 10), 'Palestine_Confront': (20, 20)}
}
israel_payoffs = [[50, 10], [70, 20]]
palestine_payoffs = [[50, 70], [10, 20]]
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))
sns.heatmap(israel_payoffs, annot=True, fmt='d', cmap='Blues', cbar=False, ax=ax1,
            xticklabels=['Palestine Cooperate', 'Palestine Confront'],
            yticklabels=['Israel Cooperate', 'Israel Confront'])
ax1.set_title('Israel Payoffs', fontsize=14)
sns.heatmap(palestine_payoffs, annot=True, fmt='d', cmap='Reds', cbar=False, ax=ax2,
            xticklabels=['Palestine Cooperate', 'Palestine Confront'],
            yticklabels=['Israel Cooperate', 'Israel Confront'])
ax2.set_title('Palestine Payoffs', fontsize=14)
