# Load data with proper CSV parsing, handling bad lines with warnings
df = pd.read_csv(StringIO(data.strip()), sep=',', quotechar='"', escapechar='\\', on_bad_lines='warn')

# Helper function to extract numeric values, handling complex formats
def extract_numeric(value):
    if pd.isna(value) or not isinstance(value, str):
        return None
    try:
        # Handle ideology scores or numeric values within text
        match = re.search(r'([-+]?\d*\.?\d+)', value)
        return float(match.group(1)) if match else None
    except (AttributeError, ValueError):
        return None

# --------------------------
# 1. Enhanced Payoff Matrix (Data-Driven)
# --------------------------
# Normalize economic impacts: Gaza (-81%) = 19/100, West Bank (-19%) = 81/100, Israel (-5%) = 95/100
payoff_matrix = {
    'Israel_Cooperate': {'Palestine_Cooperate': (60, 60), 'Palestine_Confront': (30, 70)},
    'Israel_Confront': {'Palestine_Cooperate': (70, 30), 'Palestine_Confront': (40, 20)}
}

fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))
sns.heatmap([[60, 30], [70, 40]], annot=True, fmt='d', cmap='Blues', cbar=False, ax=ax1,
            xticklabels=['Palestine Cooperate', 'Palestine Confront'],
            yticklabels=['Israel Cooperate', 'Israel Confront'])
ax1.set_title('Israel Payoffs\n(GDP Impact: -5% → 95/100)', fontsize=12)

sns.heatmap([[60, 70], [30, 20]], annot=True, fmt='d', cmap='Reds', cbar=False, ax=ax2,
            xticklabels=['Palestine Cooperate', 'Palestine Confront'],
            yticklabels=['Israel Cooperate', 'Israel Confront'])
ax2.set_title('Palestine Payoffs\n(Gaza: -81% → 19/100, WB: -19% → 81/100)', fontsize=12)
plt.suptitle("2023 Payoff Matrix: Normalized Economic Impacts", y=1.05, fontsize=16)
plt.tight_layout()
plt.show()

# --------------------------
# 2. Expanded Game Tree (2023 Escalation)
# --------------------------
dot = Digraph(comment='2023 Escalation Sequential Game', graph_attr={'rankdir': 'LR', 'splines': 'ortho'})
dot.attr('node', shape='box', style='filled', fontname='Arial')

# Define nodes with consistent styling and payoffs
nodes = {
    'A': 'Hamas Attack\n(Oct 7, 2023)\nEscalation: 9',
    'B': 'Israel Response\n(Netanyahu)\nPressure: 9',
    'C': 'Hamas Counter\n(Civilian Targets)',
    'D': 'Mediation Efforts\n(Biden/Blinken)\nPressure: 6',
    'E': 'Partial Ceasefire\n(Israel: 60, Palestine: 60)',
    'F': 'Continued Conflict\n(Israel: 40, Palestine: 20)\nGDP Impact: -5%/-81%',
    'G': 'Escalate Further\n(Israel: 30, Palestine: 10)'
}

# Assign colors: red for conflict, blue for diplomacy
for node_id, label in nodes.items():
    if 'Hamas' in label or 'Conflict' in label:
        dot.node(node_id, label, fillcolor='#ffcccc', style='filled')  # Red for conflict
    else:
        dot.node(node_id, label, fillcolor='#cce5ff', style='filled')  # Blue for diplomacy

# Define edges with probabilities and labels
dot.edge('A', 'B', label='Initial Strike')
dot.edge('B', 'C', label='Retaliation')
dot.edge('C', 'D', label='Intl. Pressure (60%)')
dot.edge('D', 'E', label='Mediation Success (60%)')
dot.edge('D', 'F', label='Mediation Fails (40%)')
dot.edge('C', 'G', label='High Pressure (70%)')

# Render and display the graph, with error handling for file existence
try:
    dot.render('game_tree_2023', view=True, format='png', cleanup=True)
    display(Image(filename='game_tree_2023.png'))
except FileNotFoundError:
    print("Graphviz rendering failed. Ensure Graphviz is installed and PATH is configured correctly.")
except Exception as e:
    print(f"Graphviz error: {e}")
print("Expanded Game Tree displayed above (if rendered successfully).")

# --------------------------
# 3. Repeated Games Analysis (1978–2023)
# --------------------------
# Filter and pivot game-theoretic metrics
game_metrics = df[df['Category'].str.contains('Behavioral Game Theory|Behavioral Factors')].copy()
game_metrics['Value'] = game_metrics['Value'].astype(str)

# Extract numeric values for game metrics
for field in ['Concession_Size', 'Escalation_Level', 'Trust Level']:
    game_metrics.loc[game_metrics['Field'] == field, 'Numeric_Value'] = game_metrics[game_metrics['Field'] == field]['Value'].apply(extract_numeric)

# Map bounded rationality
game_metrics.loc[game_metrics['Field'] == 'Bounded Rationality Impact', 'Numeric_Value'] = game_metrics[game_metrics['Field'] == 'Bounded Rationality Impact']['Value'].map({'Low': 1, 'Moderate': 2, 'High': 3})

# Pivot table for visualization
pivot_metrics = game_metrics.pivot_table(index='Event', columns='Field', values='Numeric_Value', aggfunc='first').reset_index()

# Extract ideology scores for annotations
ideology = df[df['Field'].str.contains('Ideology Score')].copy()
ideology['Ideology_Value'] = ideology['Value'].apply(lambda x: float(re.search(r'([-+]?\d*\.?\d+)', str(x)).group(1)) if re.search(r'([-+]?\d*\.?\d+)', str(x)) else None)
ideology_dict = dict(zip(ideology['Event'], ideology['Ideology_Value'].astype(str).str.replace('-0.0', '0').str.replace('+0.0', '0')))

fig, ax1 = plt.subplots(figsize=(14, 7))
for metric in ['Concession_Size', 'Escalation_Level', 'Trust Level']:
    ax1.plot(pivot_metrics['Event'], pivot_metrics[metric], marker='o', label=metric, linewidth=2, color={'Concession_Size': '#1f77b4', 'Escalation_Level': '#d62728', 'Trust Level': '#2ca02c'}[metric])

ax2 = ax1.twinx()
ax2.plot(pivot_metrics['Event'], pivot_metrics['Bounded Rationality Impact'], 'm--', marker='s', label='Bounded Rationality', linewidth=2)

# Annotate ideology scores
for event in pivot_metrics['Event']:
    if event in ideology_dict:
        x_pos = pivot_metrics.index[pivot_metrics['Event'] == event][0]
        y_pos = pivot_metrics.loc[pivot_metrics['Event'] == event, 'Bounded Rationality Impact'].values[0] + 0.1
        ax2.text(event, y_pos, f"Ideology: {ideology_dict[event]}", ha='center', fontsize=9, color='black', rotation=45)

ax1.set_title("Repeated Games Dynamics (1978–2023)\nTrust vs. Bounded Rationality with Ideology Annotations", pad=20, fontsize=16)
ax1.set_xlabel('Critical Junctures', fontsize=12)
ax1.set_ylabel('Level (0-10)', fontsize=12)
ax1.grid(True, linestyle='--', alpha=0.5)
ax1.set_xticklabels(pivot_metrics['Event'], rotation=45, fontsize=10)
ax1.legend(loc='upper left', fontsize=10)

ax2.set_ylabel('Bounded Rationality Impact (1=Low, 3=High)', fontsize=12)
ax2.set_yticks([1, 2, 3])
ax2.set_yticklabels(['Low', 'Moderate', 'High'], fontsize=10)
ax2.legend(loc='upper right', fontsize=10)

plt.tight_layout()
plt.show()

# --------------------------
# 4. Public Pressure Analysis (2023)
# --------------------------
pressure = df[(df['Event'] == '2023 Escalation') &
              (df['Field'].str.contains('Public Pressure Score'))].copy()
pressure['Leader'] = pressure['Field'].str.split(' - ').str[0]
pressure['Public_Pressure_Score'] = pressure['Value'].astype(float)

plt.figure(figsize=(12, 6))
sns.barplot(x='Leader', y='Public_Pressure_Score', data=pressure, palette='viridis',
            order=pressure.sort_values('Public_Pressure_Score', ascending=False)['Leader'])
plt.title("2023 Public Pressure Scores\n(Normalized to Netanyahu's Score=9)", fontsize=14)
plt.xlabel('Leader', fontsize=12)
plt.ylabel('Public Pressure Score (0-10)', fontsize=12)
plt.xticks(rotation=45, ha='right', fontsize=10)
plt.tight_layout()
plt.show()

