# Load data with proper CSV parsing, handling bad lines with warnings
df = pd.read_csv(StringIO(data.strip()), sep=',', quotechar='"', escapechar='\\', on_bad_lines='warn')

# Helper function to extract numeric values, handling complex formats
def extract_numeric(value):
    if pd.isna(value) or not isinstance(value, str):
        return None
    try:
        # Handle ideology scores or numeric values within text
        match = re.search(r'([-+]?\d*\.?\d+)', value)
        return float(match.group(1)) if match else None
    except (AttributeError, ValueError):
        return None

