# 2. Expanded Game Tree (2023 Escalation)
# --------------------------
dot = Digraph(comment='2023 Escalation Sequential Game', graph_attr={'rankdir': 'LR', 'splines': 'ortho'})
dot.attr('node', shape='box', style='filled', fontname='Arial')

# Define nodes with consistent styling, exact payoffs, and probabilities
nodes = {
    'A': 'Hamas Attack\n(Oct 7, 2023)\nEscalation: 9',
    'B': 'Israel Response\n(Netanyahu)\nPressure: 9',
    'C': 'Hamas Counter\n(Civilian Targets)',
    'D': 'Mediation Efforts\n(Biden/Blinken)\nPressure: 6',
    'E': 'Partial Ceasefire\n(Israel: 60, Palestine: 60)',
    'F': 'Continued Conflict\n(Israel: 40, Palestine: 20)\nGDP Impact: -5%/-81%',
    'G': 'Escalate Further\n(Israel: 30, Palestine: 10)'
}

# Assign colors: red for conflict, blue for diplomacy
for node_id, label in nodes.items():
    if 'Hamas' in label or 'Conflict' in label:
        dot.node(node_id, label, fillcolor='#ffcccc', style='filled')  # Red for conflict
    else:
        dot.node(node_id, label, fillcolor='#cce5ff', style='filled')  # Blue for diplomacy

# Define edges with exact probabilities and labels
dot.edge('A', 'B', label='Initial Strike')
dot.edge('B', 'C', label='Retaliation')
dot.edge('C', 'D', label='Intl. Pressure (60%)')
dot.edge('D', 'E', label='Mediation Success (60%)')
dot.edge('D', 'F', label='Mediation Fails (40%)')
dot.edge('C', 'G', label='High Pressure (70%)')

