import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

# Payoff function with historical context
def get_payoff(action_IL, action_PL, intL_mediates, hamas_escalates, round):
    base_payoffs = {
        ('C', 'C'): (3, 3),
        ('C', 'D'): (0, 5),
        ('D', 'C'): (5, 0),
        ('D', 'D'): (1, 1)
    }
    payoff_IL, payoff_PL = base_payoffs[(action_IL, action_PL)]
    # Adjust for Camp David mediation success (dataset: Carter's mediation)
    if round == 0 and intL_mediates and action_IL == 'C' and action_PL == 'C':
        payoff_IL, payoff_PL = 4, 4  # Higher payoff for successful mediation
    # Adjust for Oslo mutual recognition (dataset: mutual recognition milestone)
    if round == 1 and action_IL == 'C' and action_PL == 'C':
        payoff_IL, payoff_PL = 3.5, 4  # PL gains more (Palestinian Authority formation)
    # Adjust for 2023 escalation (dataset: Hamas attack, Israel-Gaza War)
    if round == 2 and hamas_escalates and action_IL == 'D':
        payoff_IL = 6  # Higher IL payoff for security focus
        payoff_PL = -1  # Lower PL payoff for economic devastation
    return payoff_IL, payoff_PL

# Simulation parameters
num_rounds = 3
wing_scores = {
    0: {'IL': 0.8, 'PL': -0.4},  # Camp David: Begin (+0.8), Sadat (-0.4)
    1: {'IL': -0.4, 'PL': -0.6}, # Oslo: Rabin (-0.4), Arafat (-0.8)
    2: {'IL': 0.6, 'PL': -0.8}   # 2023: Netanyahu (+1.0), Abbas (-1.0)
}
# Align trust with dataset: Camp David (7/10), Oslo (6/10), 2023 (3/10)
trust = 0.7  # Initial trust scaled to dataset

# Initialize state variables
P_C_IL = 0.5 - 0.4 * wing_scores[0]['IL']  # Stronger ideological impact
P_C_PL = 0.5 - 0.4 * wing_scores[0]['PL']
history = {
    'actions_IL': [], 'actions_PL': [],
    'payoffs_IL': [], 'payoffs_PL': [],
    'P_C_IL': [P_C_IL], 'P_C_PL': [P_C_PL],
    'trust': [trust]
}

# Simulate rounds
np.random.seed(42)
for round in range(num_rounds):
    # Misperception probabilities
    misp_prob_IL = 0.1 + 0.2 * max(0, wing_scores[round]['IL'])
    misp_prob_PL = 0.1 + 0.2 * max(0, wing_scores[round]['PL'])

    # Adjust P_C with trust and ideology
    P_C_IL = np.clip(P_C_IL + 0.1 * trust, 0, 1)
    P_C_PL = np.clip(P_C_PL + 0.1 * trust, 0, 1)
    if round > 0:
        P_C_IL = (P_C_IL + (0.5 - 0.4 * wing_scores[round]['IL'])) / 2
        P_C_PL = (P_C_PL + (0.5 - 0.4 * wing_scores[round]['PL'])) / 2

    # Choose actions (initial actions, then adjust for historical outcomes)
    action_IL = 'C' if np.random.rand() < P_C_IL else 'D'
    action_PL = 'C' if np.random.rand() < P_C_PL else 'D'

    # Override actions based on historical outcomes (dataset: final agreements)
    if round == 0:  # Camp David: Both cooperate by end (Final Agreement: Sep 17, 1978)
        action_IL, action_PL = 'C', 'C'
    elif round == 1:  # Oslo: Both cooperate (Mutual Recognition, Sep 13, 1993)
        action_IL, action_PL = 'C', 'C'
    # 2023: Keep simulated actions (escalation context)

    history['actions_IL'].append(action_IL)
    history['actions_PL'].append(action_PL)

    # Perceive actions
    perceived_PL = action_PL if np.random.rand() > misp_prob_IL else ('D' if action_PL == 'C' else 'C')
    perceived_IL = action_IL if np.random.rand() > misp_prob_PL else ('D' if action_IL == 'C' else 'C')

    # External influences
    intL_mediates = np.random.rand() < 0.5
    hamas_escalates = np.random.rand() < 0.3 and action_PL == 'D'

    # Update P_C based on perceived actions
    P_C_IL = min(1.0, P_C_IL + 0.05) if perceived_PL == 'C' else max(0.0, P_C_IL - 0.05)
    P_C_PL = min(1.0, P_C_PL + 0.05) if perceived_IL == 'C' else max(0.0, P_C_PL - 0.05)

    # Update trust to align with dataset (7 → 6 → 3)
    if round == 0:
        trust = 0.7  # Camp David: Trust Level 7/10
    elif round == 1:
        trust = 0.6  # Oslo: Trust Level 6/10
    else:
        trust = 0.3  # 2023: Trust Level 3/10

    # Calculate payoffs
    payoff_IL, payoff_PL = get_payoff(action_IL, action_PL, intL_mediates, hamas_escalates, round)
    history['payoffs_IL'].append(payoff_IL)
    history['payoffs_PL'].append(payoff_PL)
    history['P_C_IL'].append(P_C_IL)
    history['P_C_PL'].append(P_C_PL)
    history['trust'].append(trust)

# Visualizations
# 1. Actions Heatmap
action_map = {'C': 1, 'D': 0}
actions_matrix = np.array([
    [action_map[a] for a in history['actions_IL']],
    [action_map[a] for a in history['actions_PL']]
])
plt.figure(figsize=(8, 4))
sns.heatmap(actions_matrix, annot=True, fmt='.0f', cmap='RdYlBu', cbar=False,
            xticklabels=['Camp David', 'Oslo', '2023'], yticklabels=['IL', 'PL'])
plt.title('Actions Over Rounds (1 = Cooperate, 0 = Defect)')
plt.tight_layout()
plt.savefig('actions_heatmap_updated.png', dpi=300)

# 2. Payoffs Over Time
plt.figure(figsize=(12, 6))
plt.plot(range(num_rounds), history['payoffs_IL'], marker='o', label='IL Payoff')
plt.plot(range(num_rounds), history['payoffs_PL'], marker='o', label='PL Payoff')
plt.xticks(range(num_rounds), ['Camp David', 'Oslo', '2023'])
plt.xlabel('Round')
plt.ylabel('Payoff')
plt.title('Payoffs Over Time')
plt.legend()
plt.grid(True)
plt.tight_layout()
plt.savefig('payoffs_updated.png', dpi=300)

# 3. Cooperation Probabilities and Trust
plt.figure(figsize=(12, 6))
plt.plot(range(num_rounds + 1), history['P_C_IL'], marker='o', label='IL Cooperation Probability')
plt.plot(range(num_rounds + 1), history['P_C_PL'], marker='o', label='PL Cooperation Probability')
plt.plot(range(num_rounds + 1), history['trust'], marker='s', label='Trust Level (Dataset: 7, 6, 3)')
plt.xticks(range(num_rounds + 1), ['Start', 'Camp David', 'Oslo', '2023'])
plt.xlabel('Round')
plt.ylabel('Probability / Trust')
plt.title('Evolution of Cooperation Probabilities and Trust')
plt.legend()
plt.grid(True)
plt.tight_layout()
plt.savefig('cooperation_trust_updated.png', dpi=300)

# 4. Scenario Forecast Diagram (using matplotlib for simplicity)
plt.figure(figsize=(10, 6))
plt.scatter([1, 2, 3, 2, 3], [3, 4, 5, 2, 1], s=1000, alpha=0.3, color='lightyellow')
plt.text(1, 3, 'Current State', ha='center', va='center')
plt.text(2, 4, 'Left-Wing\nLeadership', ha='center', va='center')
plt.text(3, 5, 'Peace Agreement\n(Trust > 5)', ha='center', va='center')
plt.text(2, 2, 'Right-Wing\nLeadership', ha='center', va='center')
plt.text(3, 1, 'Prolonged Conflict\n(Escalation > 7)', ha='center', va='center')
plt.arrow(1, 3, 0.7, 0.8, head_width=0.05, head_length=0.1, fc='black', ec='black')
plt.arrow(1, 3, 0.7, -0.8, head_width=0.05, head_length=0.1, fc='black', ec='black')
plt.arrow(2, 4, 0.7, 0.8, head_width=0.05, head_length=0.1, fc='black', ec='black')
plt.arrow(2, 2, 0.7, -0.8, head_width=0.05, head_length=0.1, fc='black', ec='black')
plt.title('Scenario Forecast Diagram')
plt.axis('off')
plt.tight_layout()
plt.savefig('scenario_forecast_updated.png', dpi=300)

