import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
from matplotlib.patches import Patch

# Load the dataset
df = pd.read_csv('conflict_data.csv')

# --- Repeated Game Simulation Setup ---
# Define players, rounds, and behavioral parameters with BGT biases
rounds = ['Camp David Accords', 'Oslo Accords', '2023 Escalation']
wing_scores = {
    0: {'IL': 0.8, 'PL': -0.4},  # Camp David: Begin (right), Sadat (left)
    1: {'IL': -0.4, 'PL': -0.6}, # Oslo: Rabin (left), Arafat (left)
    2: {'IL': 0.6, 'PL': -0.8}   # 2023: Netanyahu (right), Abbas (left)
}
initial_trust = 5.0  # Initial trust level (0-10 scale)
P_C_IL = 0.5 - 0.3 * wing_scores[0]['IL']  # Initial cooperation probability for IL
P_C_PL = 0.5 - 0.3 * wing_scores[0]['PL']  # Initial cooperation probability for PL
bounded_rationality_factor = 0.1  # Noise to simulate bounded rationality
fairness_bias = 0.05  # Adjust payoffs for fairness
learning_rate = 0.05  # Rate at which players adapt based on past actions

# Simulation storage
history = {
    'actions_IL': [], 'actions_PL': [],
    'payoffs_IL': [], 'payoffs_PL': [],
    'trust': [initial_trust]
}

# Payoff function with mediation and fairness bias
def get_payoff(action_IL, action_PL, mediation=False):
    base_payoffs = {
        ('C', 'C'): (3, 3),
        ('C', 'D'): (0, 5),
        ('D', 'C'): (5, 0),
        ('D', 'D'): (1, 1)
    }
    payoff_IL, payoff_PL = base_payoffs[(action_IL, action_PL)]
    if mediation and action_IL == 'C' and action_PL == 'C':
        payoff_IL, payoff_PL = 4, 4  # Mediation bonus
    if action_IL == 'C' and action_PL == 'C':
        payoff_IL += fairness_bias * payoff_IL
        payoff_PL += fairness_bias * payoff_PL
    return payoff_IL, payoff_PL

# Simulate repeated game with BGT principles
np.random.seed(42)
trust = initial_trust
for round in range(len(rounds)):
    P_C_IL = np.clip(P_C_IL + learning_rate * (trust / 10 - 0.5), 0, 1)
    P_C_PL = np.clip(P_C_PL + learning_rate * (trust / 10 - 0.5), 0, 1)
    if round > 0:
        last_action_IL = history['actions_IL'][-1]
        last_action_PL = history['actions_PL'][-1]
        if last_action_PL == 'C':
            P_C_IL += learning_rate * 0.1
        elif last_action_PL == 'D':
            P_C_IL -= learning_rate * 0.1
        if last_action_IL == 'C':
            P_C_PL += learning_rate * 0.1
        elif last_action_IL == 'D':
            P_C_PL -= learning_rate * 0.1
        P_C_IL = np.clip((P_C_IL + (0.5 - 0.3 * wing_scores[round]['IL'])) / 2, 0, 1)
        P_C_PL = np.clip((P_C_PL + (0.5 - 0.3 * wing_scores[round]['PL'])) / 2, 0, 1)

    P_C_IL_noise = np.clip(P_C_IL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    P_C_PL_noise = np.clip(P_C_PL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    action_IL = 'C' if np.random.rand() < P_C_IL_noise else 'D'
    action_PL = 'C' if np.random.rand() < P_C_PL_noise else 'D'
    history['actions_IL'].append(action_IL)
    history['actions_PL'].append(action_PL)

    mediation = np.random.rand() < 0.5
    if action_IL == 'C' and action_PL == 'C':
        trust = min(10.0, trust + 1)
    elif action_IL == 'D' and action_PL == 'D':
        trust = max(0.0, trust - 2)
    else:
        trust = max(0.0, trust - 1)
    history['trust'].append(trust)

    payoff_IL, payoff_PL = get_payoff(action_IL, action_PL, mediation)
    history['payoffs_IL'].append(payoff_IL)
    history['payoffs_PL'].append(payoff_PL)

# --- 1. Payoff Matrix Over Rounds ---
payoff_labels = [f"{aIL}/{aPL}" for aIL, aPL in zip(history['actions_IL'], history['actions_PL'])]
payoff_matrix = np.array([history['payoffs_IL'], history['payoffs_PL']])

plt.figure(figsize=(10, 5))
sns.heatmap(payoff_matrix, annot=True, fmt='.2f', cmap='coolwarm', cbar=True,
            xticklabels=rounds, yticklabels=['Israeli Leadership', 'Palestinian Leadership'],
            annot_kws={'size': 12}, cbar_kws={'label': 'Payoff'})
for i, label in enumerate(payoff_labels):
    plt.text(i + 0.5, -0.1, label, ha='center', va='top', fontsize=9, transform=plt.gca().get_xaxis_transform())
plt.title('Payoff Evolution in Repeated Games', fontsize=14, pad=20)
plt.xlabel('Round', fontsize=12)
plt.ylabel('Player', fontsize=12)
plt.xticks(rotation=45, ha='right', fontsize=10)
plt.yticks(fontsize=10)
plt.text(0, 1.05, 'Note: Payoffs reflect BGT simulation with mediation, fairness, and bounded rationality.',
         fontsize=9, transform=plt.gca().transAxes, ha='left')
plt.subplots_adjust(bottom=0.25, top=0.85)
plt.tight_layout()
plt.savefig('payoff_matrix_repeated.png', dpi=300)

# --- 2. Trust and Cooperation Dynamics ---
trust_levels = history['trust'][1:]
trust_error = np.std(trust_levels) / np.sqrt(len(trust_levels)) if len(trust_levels) > 0 else 0
trust_ci = 1.96 * trust_error  # 95% confidence interval
cooperation_IL = [1 if a == 'C' else 0 for a in history['actions_IL']]
cooperation_PL = [1 if a == 'C' else 0 for a in history['actions_PL']]

plt.figure(figsize=(12, 6))
