import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
from matplotlib.patches import Patch

# Load dataset (Assuming this file exists and is relevant, though not used in simulation)
try:
    df = pd.read_csv('conflict_data.csv')
except FileNotFoundError:
    print("Warning: conflict_data.csv not found. Proceeding with simulation only.")
    df = pd.DataFrame() # Create an empty DataFrame if the file is missing


# --- Simulation Setup ---
rounds = ['Camp David', 'Oslo', '2023']
wing_scores = {
    0: {'IL': 0.8, 'PL': -0.4, 'INT': -0.2, 'NS': 0.0},
    1: {'IL': -0.4, 'PL': -0.6, 'INT': -0.3, 'NS': 0.0},
    2: {'IL': 0.6, 'PL': -0.8, 'INT': 0.0, 'NS': 0.9}
}
initial_trust = 5.0
# Initialize probabilities based on the first round's wing scores
P_C_IL = 0.5 - 0.3 * wing_scores[0]['IL']
P_C_PL = 0.5 - 0.3 * wing_scores[0]['PL']
P_C_INT = 0.5 - 0.3 * wing_scores[0]['INT'] if wing_scores[0]['INT'] != 0.0 else 0.5
P_C_NS = 0.5 - 0.3 * wing_scores[0]['NS'] if wing_scores[0]['NS'] != 0.0 else 0.5

bounded_rationality_factor = 0.1
fairness_bias = 0.05
learning_rate = 0.05
misperception_factor = 0.05

# Simulation storage
history = {
    'actions_IL': [], 'actions_PL': [], 'actions_INT': [], 'actions_NS': [],
    'payoffs_IL': [], 'payoffs_PL': [], 'payoffs_INT': [], 'payoffs_NS': [],
    'trust': [initial_trust] # Start with initial trust for the first round's outcome
}

# Payoff function
def get_payoff(action_IL, action_PL, action_INT, action_NS, mediation=False):
    base_payoffs = {
        ('C', 'C', 'C', 'C'): (3, 3, 1, 0),
        ('C', 'D', 'C', 'D'): (0, 5, 0, 1),
        ('D', 'C', 'C', 'D'): (5, 0, 0, 1),
        ('D', 'D', 'C', 'D'): (1, 1, 0, 0),
        ('C', 'C', 'D', 'C'): (2, 2, -1, 0)
    }
    # Default payoff for combinations not explicitly listed
    payoff_IL, payoff_PL, payoff_INT, payoff_NS = base_payoffs.get(
        (action_IL, action_PL, action_INT, action_NS), (1, 1, 0, 0))

    if mediation and action_IL == 'C' and action_PL == 'C' and action_INT == 'C':
        payoff_IL, payoff_PL, payoff_INT = 4, 4, 2

    if action_IL == 'C' and action_PL == 'C':
        payoff_IL += fairness_bias * payoff_IL
        payoff_PL += fairness_bias * payoff_PL

    return payoff_IL, payoff_PL, payoff_INT, payoff_NS

# Simulate game
np.random.seed(42)
trust = initial_trust

# Use the initial probabilities for the first round
current_P_C_IL = P_C_IL
current_P_C_PL = P_C_PL
current_P_C_INT = P_C_INT
current_P_C_NS = P_C_NS

for round_idx in range(len(rounds)):
    # Update probabilities based on the outcome of the *previous* round
    if round_idx > 0:
        last_actions = {
            'IL': history['actions_IL'][-1],
            'PL': history['actions_PL'][-1],
            'INT': history['actions_INT'][-1],
            'NS': history['actions_NS'][-1]
        }

        for actor, action in last_actions.items():
            if actor == 'IL':
                change = learning_rate * 0.1 if action == 'C' else -learning_rate * 0.1
                current_P_C_IL = np.clip(current_P_C_IL + change, 0, 1)
                # Incorporate wing scores influence
                current_P_C_IL = np.clip((current_P_C_IL + (0.5 - 0.3 * wing_scores[round_idx][actor])) / 2, 0, 1)
            elif actor == 'PL':
                change = learning_rate * 0.1 if action == 'C' else -learning_rate * 0.1
                current_P_C_PL = np.clip(current_P_C_PL + change, 0, 1)
                # Incorporate wing scores influence
                current_P_C_PL = np.clip((current_P_C_PL + (0.5 - 0.3 * wing_scores[round_idx][actor])) / 2, 0, 1)
            elif actor == 'INT' and wing_scores[round_idx]['INT'] != 0.0:
                change = learning_rate * 0.1 if action == 'C' else -learning_rate * 0.1
                current_P_C_INT = np.clip(current_P_C_INT + change, 0, 1)
                # Incorporate wing scores influence
                current_P_C_INT = np.clip((current_P_C_INT + (0.5 - 0.3 * wing_scores[round_idx][actor])) / 2, 0, 1)
            elif actor == 'NS' and wing_scores[round_idx]['NS'] != 0.0:
                change = learning_rate * 0.1 if action == 'C' else -learning_rate * 0.1
                current_P_C_NS = np.clip(current_P_C_NS + change, 0, 1)
                 # Incorporate wing scores influence
                current_P_C_NS = np.clip((current_P_C_NS + (0.5 - 0.3 * wing_scores[round_idx][actor])) / 2, 0, 1)


    # Incorporate trust and misperception for the current round's probabilities
    prob_IL = np.clip(current_P_C_IL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1)
    prob_PL = np.clip(current_P_C_PL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1)
    prob_INT = np.clip(current_P_C_INT + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1) if wing_scores[round_idx]['INT'] != 0.0 else 0.5
    prob_NS = np.clip(current_P_C_NS + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1) if wing_scores[round_idx]['NS'] != 0.0 else 0.5


    # Add bounded rationality noise before making a decision
    P_C_IL_noise = np.clip(prob_IL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    P_C_PL_noise = np.clip(prob_PL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    P_C_INT_noise = np.clip(prob_INT + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1) if wing_scores[round_idx]['INT'] != 0.0 else 0.5
    P_C_NS_noise = np.clip(prob_NS + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1) if wing_scores[round_idx]['NS'] != 0.0 else 0.5


    action_IL = 'C' if np.random.rand() < P_C_IL_noise else 'D'
    action_PL = 'C' if np.random.rand() < P_C_PL_noise else 'D'
    action_INT = 'C' if np.random.rand() < P_C_INT_noise else 'D' if wing_scores[round_idx]['INT'] != 0.0 else 'N/A'
    action_NS = 'C' if np.random.rand() < P_C_NS_noise else 'D' if wing_scores[round_idx]['NS'] != 0.0 else 'N/A'


    history['actions_IL'].append(action_IL)
    history['actions_PL'].append(action_PL)
    history['actions_INT'].append(action_INT)
    history['actions_NS'].append(action_NS)

    mediation = np.random.rand() < 0.5 and action_INT == 'C' if wing_scores[round_idx]['INT'] != 0.0 and action_INT != 'N/A' else False


    # Update trust based on the current round's actions
    # Trust dynamics include all actors if they are active in the round
    trust_change = 0
    if action_IL == 'C' and action_PL == 'C':
        trust_change += 1 # Mutual cooperation increases trust
        if action_INT == 'C' and wing_scores[round_idx]['INT'] != 0.0: trust_change += 0.5 # INT cooperation also helps
    elif action_IL == 'D' and action_PL == 'D':
        trust_change -= 2 # Mutual defection decreases trust
        if action_NS == 'D' and wing_scores[round_idx]['NS'] != 0.0: trust_change -= 0.5 # NS defection worsens it
    elif action_IL != action_PL:
         trust_change -= 1 # Mixed outcome decreases trust


    # Trust also influenced by INT and NS actions if active
    if wing_scores[round_idx]['INT'] != 0.0:
        if action_INT == 'C': trust_change += 0.2 # INT cooperation
        elif action_INT == 'D': trust_change -= 0.2 # INT defection

    if wing_scores[round_idx]['NS'] != 0.0:
        if action_NS == 'C': trust_change -= 0.3 # NS cooperation is adversarial to peace (reduces trust)
        elif action_NS == 'D': trust_change += 0.3 # NS defection is less adversarial (increases trust)

    trust = np.clip(trust + trust_change, 0.0, 10.0)

    # Record trust *after* the actions and trust update
    history['trust'].append(trust)


    payoff_IL, payoff_PL, payoff_INT, payoff_NS = get_payoff(action_IL, action_PL, action_INT, action_NS, mediation)

    # Adjust payoffs for 'N/A' actors (they get 0 in the payoff matrix)
    final_payoff_INT = payoff_INT if action_INT != 'N/A' else 0
    final_payoff_NS = payoff_NS if action_NS != 'N/A' else 0

    history['payoffs_IL'].append(payoff_IL)
    history['payoffs_PL'].append(payoff_PL)
    history['payoffs_INT'].append(final_payoff_INT)
    history['payoffs_NS'].append(final_payoff_NS)


# Remove the initial trust value which was just a starting point
trust_levels = history['trust'][1:]

# --- 1. Payoff Matrix ---
payoff_matrix = np.array([
    history['payoffs_IL'],
    history['payoffs_PL'],
    history['payoffs_INT'],
    history['payoffs_NS']
])

plt.figure(figsize=(8, 6))
sns.heatmap(payoff_matrix, annot=True, fmt='.2f', cmap='coolwarm', cbar=True,
            xticklabels=rounds, yticklabels=['IL', 'PL', 'INT', 'NS'],
            annot_kws={'size': 8}, cbar_kws={'label': 'Payoff'}, # Removed labelpad
            linewidths=0.5, linecolor='gray')
plt.title('Payoff Evolution', fontsize=12, pad=10)
plt.xlabel('Round', fontsize=10, labelpad=5)
plt.ylabel('Actor', fontsize=10, labelpad=5)
plt.xticks(rotation=45, ha='right', fontsize=9)
plt.yticks(fontsize=9)
plt.text(0, 1.02, 'Note: BGT simulation with mediation, fairness, bounded rationality',
         fontsize=8, transform=plt.gca().transAxes, ha='left')
plt.tight_layout()
plt.savefig('payoff_matrix_enhanced.png', dpi=300, bbox_inches='tight')


# --- 2. Trust and Cooperation Dynamics ---
trust_error = np.std(trust_levels) / np.sqrt(len(trust_levels)) if len(trust_levels) > 0 else 0
trust_ci = 1.96 * trust_error

cooperation_IL = [1 if a == 'C' else 0 for a in history['actions_IL']]
cooperation_PL = [1 if a == 'C' else 0 for a in history['actions_PL']]
# Cooperation for INT and NS only if they were active in that round
cooperation_INT_plot = [1 if a == 'C' else 0 if a == 'D' else np.nan for a in history['actions_INT']] # Use NaN for N/A
cooperation_NS_plot = [1 if a == 'C' else 0 if a == 'D' else np.nan for a in history['actions_NS']] # Use NaN for N/A

fig, ax1 = plt.subplots(figsize=(8, 5))
ax1.plot(range(len(rounds)), trust_levels, '-o', color='#6A0573', label='Trust', linewidth=1, markersize=4)
ax1.fill_between(range(len(rounds)), np.array(trust_levels) - trust_ci, np.array(trust_levels) + trust_ci,
                 color='#6A0573', alpha=0.1)
ax1.set_xlabel('Round', fontsize=10, labelpad=5)
ax1.set_ylabel('Trust', fontsize=10, labelpad=5, color='#6A0573')
ax1.tick_params(axis='y', labelcolor='#6A0573')
ax1.set_ylim(0, 10)
ax1.grid(True, linestyle='--', alpha=0.5)

