import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
from matplotlib.patches import Patch

# Load dataset
df = pd.read_csv('conflict_data.csv')

# --- Simulation Setup ---
rounds = ['Camp David', 'Oslo', '2023']
wing_scores = {
    0: {'IL': 0.8, 'PL': -0.4, 'INT': -0.2, 'NS': 0.0},
    1: {'IL': -0.4, 'PL': -0.6, 'INT': -0.3, 'NS': 0.0},
    2: {'IL': 0.6, 'PL': -0.8, 'INT': 0.0, 'NS': 0.9}
}
initial_trust = 5.0
P_C_IL = 0.5 - 0.3 * wing_scores[0]['IL']
P_C_PL = 0.5 - 0.3 * wing_scores[0]['PL']
P_C_INT = 0.5 - 0.3 * wing_scores[0]['INT']
P_C_NS = 0.5 - 0.3 * wing_scores[0]['NS'] if wing_scores[0]['NS'] != 0.0 else 0.5
bounded_rationality_factor = 0.1
fairness_bias = 0.05
learning_rate = 0.05
misperception_factor = 0.05

# Simulation storage
history = {
    'actions_IL': [], 'actions_PL': [], 'actions_INT': [], 'actions_NS': [],
    'payoffs_IL': [], 'payoffs_PL': [], 'payoffs_INT': [], 'payoffs_NS': [],
    'trust': [initial_trust]
}

# Payoff function
def get_payoff(action_IL, action_PL, action_INT, action_NS, mediation=False):
    base_payoffs = {
        ('C', 'C', 'C', 'C'): (3, 3, 1, 0),
        ('C', 'D', 'C', 'D'): (0, 5, 0, 1),
        ('D', 'C', 'C', 'D'): (5, 0, 0, 1),
        ('D', 'D', 'C', 'D'): (1, 1, 0, 0),
        ('C', 'C', 'D', 'C'): (2, 2, -1, 0)
    }
    payoff_IL, payoff_PL, payoff_INT, payoff_NS = base_payoffs.get(
        (action_IL, action_PL, action_INT, action_NS), (1, 1, 0, 0))
    if mediation and action_IL == 'C' and action_PL == 'C' and action_INT == 'C':
        payoff_IL, payoff_PL, payoff_INT = 4, 4, 2
    if action_IL == 'C' and action_PL == 'C':
        payoff_IL += fairness_bias * payoff_IL
        payoff_PL += fairness_bias * payoff_PL
    return payoff_IL, payoff_PL, payoff_INT, payoff_NS

# Simulate game
np.random.seed(42)
trust = initial_trust
for round_idx in range(len(rounds)):
    P_C_IL = np.clip(P_C_IL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1)
    P_C_PL = np.clip(P_C_PL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1)
    P_C_INT = np.clip(P_C_INT + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1) if wing_scores[round_idx]['INT'] != 0.0 else 0.5
    P_C_NS = np.clip(P_C_NS + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1) if wing_scores[round_idx]['NS'] != 0.0 else 0.5
    if round_idx > 0:
        for last_action in [history['actions_IL'][-1], history['actions_PL'][-1], history['actions_INT'][-1], history['actions_NS'][-1]]:
            if last_action == 'C':
                P_C_IL += learning_rate * 0.1
                P_C_PL += learning_rate * 0.1
                if wing_scores[round_idx]['INT'] != 0.0: P_C_INT += learning_rate * 0.1
                if wing_scores[round_idx]['NS'] != 0.0: P_C_NS += learning_rate * 0.1
            elif last_action == 'D':
                P_C_IL -= learning_rate * 0.1
                P_C_PL -= learning_rate * 0.1
                if wing_scores[round_idx]['INT'] != 0.0: P_C_INT -= learning_rate * 0.1
                if wing_scores[round_idx]['NS'] != 0.0: P_C_NS -= learning_rate * 0.1
        P_C_IL = np.clip((P_C_IL + (0.5 - 0.3 * wing_scores[round_idx]['IL'])) / 2, 0, 1)
        P_C_PL = np.clip((P_C_PL + (0.5 - 0.3 * wing_scores[round_idx]['PL'])) / 2, 0, 1)
        if wing_scores[round_idx]['INT'] != 0.0:
            P_C_INT = np.clip((P_C_INT + (0.5 - 0.3 * wing_scores[round_idx]['INT'])) / 2, 0, 1)
        if wing_scores[round_idx]['NS'] != 0.0:
            P_C_NS = np.clip((P_C_NS + (0.5 - 0.3 * wing_scores[round_idx]['NS'])) / 2, 0, 1)

    P_C_IL_noise = np.clip(P_C_IL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    P_C_PL_noise = np.clip(P_C_PL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    P_C_INT_noise = np.clip(P_C_INT + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1) if wing_scores[round_idx]['INT'] != 0.0 else 0.5
    P_C_NS_noise = np.clip(P_C_NS + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1) if wing_scores[round_idx]['NS'] != 0.0 else 0.5
    action_IL = 'C' if np.random.rand() < P_C_IL_noise else 'D'
    action_PL = 'C' if np.random.rand() < P_C_PL_noise else 'D'
    action_INT = 'C' if np.random.rand() < P_C_INT_noise else 'D' if wing_scores[round_idx]['INT'] != 0.0 else 'N/A'
    action_NS = 'C' if np.random.rand() < P_C_NS_noise else 'D' if wing_scores[round_idx]['NS'] != 0.0 else 'N/A'
    history['actions_IL'].append(action_IL)
    history['actions_PL'].append(action_PL)
    history['actions_INT'].append(action_INT)
    history['actions_NS'].append(action_NS)

    mediation = np.random.rand() < 0.5 and action_INT == 'C' if wing_scores[round_idx]['INT'] != 0.0 else False
    if action_IL == 'C' and action_PL == 'C' and (action_INT == 'C' or wing_scores[round_idx]['INT'] == 0.0):
        trust = min(10.0, trust + 1)
    elif action_IL == 'D' and action_PL == 'D' and (action_INT == 'D' or wing_scores[round_idx]['INT'] == 0.0):
        trust = max(0.0, trust - 2)
    else:
        trust = max(0.0, trust - 1)
    history['trust'].append(trust)

    payoff_IL, payoff_PL, payoff_INT, payoff_NS = get_payoff(action_IL, action_PL, action_INT, action_NS, mediation)
    history['payoffs_IL'].append(payoff_IL)
    history['payoffs_PL'].append(payoff_PL)
    history['payoffs_INT'].append(payoff_INT if wing_scores[round_idx]['INT'] != 0.0 else 0)
    history['payoffs_NS'].append(payoff_NS if wing_scores[round_idx]['NS'] != 0.0 else 0)

# --- 1. Combined Payoff and Action Heatmap ---
payoff_matrix = np.array([
    history['payoffs_IL'], history['payoffs_PL'],
    [p if s['INT'] != 0.0 else 0 for p, s in zip(history['payoffs_INT'], [wing_scores[i] for i in range(len(rounds))])],
    [p if s['NS'] != 0.0 else 0 for p, s in zip(history['payoffs_NS'], [wing_scores[i] for i in range(len(rounds))])]
])
action_map = {'C': 1, 'D': 0, 'N/A': 0.5}
actions_matrix = np.array([
    [action_map[a] for a in history['actions_IL']],
    [action_map[a] for a in history['actions_PL']],
    [action_map[a] if wing_scores[i]['INT'] != 0.0 else 0.5 for a, i in zip(history['actions_INT'], range(len(rounds)))],
    [action_map[a] if wing_scores[i]['NS'] != 0.0 else 0.5 for a, i in zip(history['actions_NS'], range(len(rounds)))]
])

fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(8, 10), gridspec_kw={'height_ratios': [2, 1]}, sharex=True)
sns.heatmap(payoff_matrix, annot=True, fmt='.2f', cmap='coolwarm', cbar=True, ax=ax1,
            xticklabels=rounds, yticklabels=['IL', 'PL', 'INT', 'NS'],
            annot_kws={'size': 8}, cbar_kws={'label': 'Payoff'}, # Removed labelpad
            linewidths=0.5, linecolor='gray')
sns.heatmap(actions_matrix, annot=True, fmt='.1f', cmap='RdYlBu_r', cbar=True, ax=ax2,
            xticklabels=rounds, yticklabels=['IL', 'PL', 'INT', 'NS'],
            annot_kws={'size': 8}, cbar_kws={'label': 'Action (1=C, 0=D, 0.5=N/A)'}, # Removed labelpad
            linewidths=0.5, linecolor='gray')
for i in range(len(rounds)):
    for j in range(4):
        if (j == 2 and wing_scores[i]['INT'] != 0.0) or (j == 3 and wing_scores[i]['NS'] != 0.0):
            ax2.add_patch(plt.Rectangle((i, j), 1, 1, fill=False, edgecolor='black', lw=1))
ax1.set_title('Payoff and Action Evolution', fontsize=12, pad=10)
ax1.set_ylabel('Actor', fontsize=10, labelpad=5)
ax2.set_xlabel('Round', fontsize=10, labelpad=5)
ax2.set_ylabel('Actor', fontsize=10, labelpad=5)
plt.xticks(rotation=45, ha='right', fontsize=9)
plt.yticks(fontsize=9)
ax2.legend(handles=[Patch(color='#1F77B4', label='C'), Patch(color='#D62728', label='D'), Patch(color='#808080', label='N/A')],
           loc='upper right', fontsize=8)
plt.tight_layout()
plt.savefig('combined_payoff_action_heatmap.png', dpi=300, bbox_inches='tight')

# --- 2. Trust and Cooperation Dynamics with Actions ---
trust_levels = history['trust'][1:]
trust_error = np.std(trust_levels) / np.sqrt(len(trust_levels)) if len(trust_levels) > 0 else 0
trust_ci = 1.96 * trust_error
cooperation_IL = [1 if a == 'C' else 0 for a in history['actions_IL']]
cooperation_PL = [1 if a == 'C' else 0 for a in history['actions_PL']]
cooperation_INT = [1 if history['actions_INT'][i] == 'C' else 0 if history['actions_INT'][i] == 'D' else 0.5 for i in range(len(rounds))]
cooperation_NS = [1 if history['actions_NS'][i] == 'C' else 0 if history['actions_NS'][i] == 'D' else 0.5 for i in range(len(rounds))]


fig, ax1 = plt.subplots(figsize=(8, 5))
ax1.plot(range(len(rounds)), trust_levels, '-o', color='#6A0573', label='Trust', linewidth=1, markersize=4)
ax1.fill_between(range(len(rounds)), np.array(trust_levels) - trust_ci, np.array(trust_levels) + trust_ci,
                 color='#6A0573', alpha=0.1)
ax1.set_xlabel('Round', fontsize=10, labelpad=5)
ax1.set_ylabel('Trust', fontsize=10, labelpad=5, color='#6A0573')
ax1.tick_params(axis='y', labelcolor='#6A0573')
ax1.set_ylim(0, 10)
ax1.grid(True, linestyle='--', alpha=0.5)

ax2 = ax1.twinx()
ax2.plot(range(len(rounds)), cooperation_IL, 's-', color='#1F77B4', label='IL', linewidth=1, markersize=4)
ax2.plot(range(len(rounds)), cooperation_PL, '^-', color='#2CA02C', label='PL', linewidth=1, markersize=4)
ax2.plot(range(len(rounds)), cooperation_INT, 'd-', color='#FF7F0E', label='INT', linewidth=1, markersize=4)
ax2.plot(range(len(rounds)), cooperation_NS, '*-', color='#D62728', label='NS', linewidth=1, markersize=4)
ax2.set_ylabel('Cooperation (1=C, 0=D)', fontsize=10, labelpad=5, color='#1F77B4')
ax2.tick_params(axis='y', labelcolor='#1F77B4')
ax2.set_ylim(-0.1, 1.1)

for i, (a_il, a_pl, a_int, a_ns) in enumerate(zip(history['actions_IL'], history['actions_PL'], history['actions_INT'], history['actions_NS'])):
    ax2.text(i, -0.1, f'{a_il}{a_pl}{a_int}{a_ns}', ha='center', va='top', fontsize=8, color='black')

plt.title('Trust and Cooperation Dynamics', fontsize=12, pad=10)
ax1.set_xticks(range(len(rounds)))
ax1.set_xticklabels(rounds, rotation=45, ha='right', fontsize=9)
ax1.tick_params(axis='y', labelsize=9)
ax2.tick_params(axis='y', labelsize=9)
lines1, labels1 = ax1.get_legend_handles_labels()
lines2, labels2 = ax2.get_legend_handles_labels()
plt.legend(lines1 + lines2, labels1 + labels2, fontsize=8, loc='upper left')
