# Imports
import pandas as pd
import matplotlib.pyplot as plt
import networkx as nx
from graphviz import Digraph
from IPython.display import Image  # For displaying images in Jupyter

# Load dataset (placeholder for conflict_data.csv)
df = pd.read_csv("conflict_data.csv")

# Utility function to build and draw decision tree using Graphviz
def draw_sequential_game(event_name, initial_actor_action_labels, il_action_labels, pl_action_labels, payoffs, metrics, file_name):
    # Create Digraph for directed graph
    G = Digraph(format='png')

    # Nodes: Initial actor (Hamas/Egypt/PLO), IL (Israel), PL (Palestine/Hamas response)
    G.node("Initial", label=event_name.split()[0], style="filled", fillcolor="lightcoral", shape="box")  # Initial actor
    G.node("IL", label="IL", style="filled", fillcolor="lightblue", shape="box")
    G.node("PL_C", label="PL", style="filled", fillcolor="lightgreen", shape="box")
    G.node("PL_D", label="PL", style="filled", fillcolor="lightgreen", shape="box")

    # Terminal nodes for outcomes
    terminals = {}
    outcomes = ['HCC', 'HCD', 'HDC', 'HDD']  # Initial-IL-PL combinations
    labels = ['({}, {})'.format(*p) for p in payoffs]

    for outcome, label in zip(outcomes, labels):
        node = "T_" + outcome
        terminals[outcome] = node
        G.node(node, label=label, style="filled", fillcolor="lightyellow", shape="circle")

    # Edges reflecting historical sequence: Initial actor → IL → PL
    G.edge("Initial", "IL", label=initial_actor_action_labels[0])
    G.edge("IL", "PL_C", label=il_action_labels[0])
    G.edge("IL", "PL_D", label=il_action_labels[1])
    G.edge("PL_C", terminals['HCC'], label=pl_action_labels[0])
    G.edge("PL_C", terminals['HCD'], label=pl_action_labels[1])
    G.edge("PL_D", terminals['HDC'], label=pl_action_labels[0])
    G.edge("PL_D", terminals['HDD'], label=pl_action_labels[1])

    # Add title and metrics as labels
    G.attr(label=f"Sequential Game for {event_name}\nDataset Metrics: {metrics}\nPayoffs: (IL, PL) | References: Trust Level, Escalation Level")
    G.attr(fontsize='12')

    # Render and save the graph
    output_file = G.render(filename=file_name, format='png', cleanup=True)

    # Display the rendered image using IPython.display.Image
    plt.figure(figsize=(12, 8))
    plt.imshow(plt.imread(output_file))
    plt.axis('off')
    plt.show()

# === Define data for each event with historical accuracy === #

# Camp David Accords (1978) - Egypt (initial actor) initiates, IL and PL respond
draw_sequential_game(
    event_name="Camp David Accords (1978)",
    initial_actor_action_labels=["A (Approach Negotiations)"],
    il_action_labels=["C (Negotiate)", "D (Resist)"],
    pl_action_labels=["C (Shift)", "D (Demand)"],
    payoffs=[(4, 4), (2, 5), (5, 2), (1, 1)],  # Calibrated for Begin (+0.8) and Sadat/Rabin moderation
    metrics="Trust Level: 7, Concession Size: 7, Escalation Level: 3",
    file_name="camp_david_sequential"
)

# Oslo Accords (1993) - PL (PLO) initiates talks, IL responds
draw_sequential_game(
    event_name="Oslo Accords (1993)",
    initial_actor_action_labels=["I (Initiate Talks)"],
    il_action_labels=["C (Engage)", "D (Status Quo)"],
    pl_action_labels=["C (Recognize)", "D (Reject)"],
    payoffs=[(3, 4), (1, 5), (4, 2), (1, 1)],  # Calibrated for Rabin (-0.4) and Arafat (-0.6)
    metrics="Trust Level: 6, Concession Size: 7, Escalation Level: 3",
    file_name="oslo_sequential"
)

# 2023 Escalation - Hamas initiates October 7 attack, IL responds, PL/Hamas reacts
draw_sequential_game(
    event_name="2023 Escalation (Post-October 7)",
    initial_actor_action_labels=["A (October 7 Attack)"],
    il_action_labels=["C (Ceasefire)", "D (Escalate)"],
    pl_action_labels=["C (Accept)", "D (Resist)"],
    payoffs=[(3, 2), (1, 4), (5, 0), (5, -1)],  # Calibrated for Netanyahu (+2.4) and Hamas asymmetry
    metrics="Trust Level: 3, Concession Size: 8, Escalation Level: 8",
    file_name="escalation_2023_sequential"
)

