# Imports
import pandas as pd
import matplotlib.pyplot as plt
import networkx as nx
from graphviz import Digraph
from IPython.display import Image

# Load dataset (placeholder for conflict_data.csv)
df = pd.read_csv("conflict_data.csv")

# Utility function to build and draw decision tree with improvements
def draw_sequential_game(event_name, initial_actor, initial_action_labels, il_action_labels, pl_action_labels,
                        secondary_il_labels, payoffs, metrics, file_name):
    G = Digraph(format='png')

    # Nodes: Initial actor, IL (Israel), PL (Palestine/Hamas), optional secondary IL
    G.node("Initial", label=f"{initial_actor}\n{initial_action_labels[0]}", style="filled", fillcolor="lightcoral", shape="box")
    G.node("IL", label="IL: Israel\n(First Response)", style="filled", fillcolor="lightblue", shape="box")
    G.node("PL_C", label="PL: Palestine/Hamas\n(Cooperate)", style="filled", fillcolor="lightgreen", shape="box")
    G.node("PL_D", label="PL: Palestine/Hamas\n(Defect)", style="filled", fillcolor="lightgreen", shape="box")

    # Optional secondary IL node for 2023 escalation
    if secondary_il_labels:
        G.node("IL2_C", label="IL: Israel\n(De-escalate)", style="filled", fillcolor="lightblue", shape="box")
        G.node("IL2_D", label="IL: Israel\n(Retaliate)", style="filled", fillcolor="lightblue", shape="box")

    # Terminal nodes for outcomes
    terminals = {}
    outcomes = ['HCC', 'HCD', 'HDC', 'HDD']  # Initial-IL-PL combinations
    if secondary_il_labels:
        outcomes.extend(['HCC_C', 'HCC_D', 'HCD_C', 'HCD_D', 'HDC_C', 'HDC_D', 'HDD_C', 'HDD_D'])
    labels = ['({}, {})'.format(*p) for p in payoffs]

    for outcome, label in zip(outcomes, labels):
        node = "T_" + outcome
        terminals[outcome] = node
        G.node(node, label=label, style="filled", fillcolor="lightyellow" if 'C' in outcome else "salmon", shape="circle")

    # Edges reflecting historical sequence
    G.edge("Initial", "IL", label=f"{initial_actor} Initiates")
