# Utility function to build and draw decision tree with improvements
def draw_sequential_game(event_name, initial_actor, initial_action_labels, il_action_labels, pl_action_labels,
                        secondary_il_labels, payoffs, metrics, file_name):
    G = Digraph(format='png')

    # Nodes: Initial actor, IL (Israel), PL (Palestine/Hamas), optional secondary IL
    G.node("Initial", label=f"{initial_actor}\n{initial_action_labels[0]}", style="filled", fillcolor="lightcoral", shape="box")
    G.node("IL", label="IL: Israel\n(First Response)", style="filled", fillcolor="lightblue", shape="box")
    G.node("PL_C", label="PL: Palestine/Hamas\n(Cooperate)", style="filled", fillcolor="lightgreen", shape="box")
    G.node("PL_D", label="PL: Palestine/Hamas\n(Defect)", style="filled", fillcolor="lightgreen", shape="box")

    # Optional secondary IL node for 2023 escalation
    if secondary_il_labels:
        G.node("IL2_C", label="IL: Israel\n(De-escalate)", style="filled", fillcolor="lightblue", shape="box")
        G.node("IL2_D", label="IL: Israel\n(Retaliate)", style="filled", fillcolor="lightblue", shape="box")

    # Terminal nodes for outcomes
    terminals = {}
    # Define base outcomes for 3 actors
    base_outcomes = [initial_action_labels[0][0] + il_action_labels[i][0] + pl_action_labels[j][0]
                     for i in range(len(il_action_labels)) for j in range(len(pl_action_labels))]
    # Ensure outcomes are unique and in a consistent order
    base_outcomes.sort() # Added sort for consistency

    all_outcomes = []
    if secondary_il_labels:
        # Generate outcomes for 4 actors
        for bo in base_outcomes:
             all_outcomes.extend([bo + secondary_il_labels[k][0] for k in range(len(secondary_il_labels))])
    else:
        all_outcomes = base_outcomes

    # Map outcomes to payoffs
    if len(all_outcomes) != len(payoffs):
        raise ValueError(f"Number of outcomes ({len(all_outcomes)}) does not match number of payoffs ({len(payoffs)}) for {event_name}")

    for i, outcome in enumerate(all_outcomes):
        node = "T_" + outcome
        terminals[outcome] = node
        # Color terminal nodes based on outcome (simplified)
        fillcolor = "lightyellow" # Default
        if outcome.endswith('C'):
            fillcolor = "lightgreen"
        elif outcome.endswith('D'):
             fillcolor = "salmon"
        G.node(node, label=f"({payoffs[i][0]}, {payoffs[i][1]})", style="filled", fillcolor=fillcolor, shape="circle")


    # Edges reflecting historical sequence
    G.edge("Initial", "IL", label=f"{initial_actor} Initiates")

    # Edges from IL to PL decisions
    G.edge("IL", "PL_C", label=il_action_labels[0]) # IL C leads to PL decision
    G.edge("IL", "PL_D", label=il_action_labels[1]) # IL D leads to PL decision

    # Edges from PL decisions to terminal nodes or secondary IL
    if secondary_il_labels:
        # Edges from PL decisions to secondary IL nodes
        G.edge("PL_C", "IL2_C", label=pl_action_labels[0]) # PL C leads to IL2 decision
        G.edge("PL_C", "IL2_D", label=pl_action_labels[0])
        G.edge("PL_D", "IL2_C", label=pl_action_labels[1]) # PL D leads to IL2 decision
        G.edge("PL_D", "IL2_D", label=pl_action_labels[1])

        # Edges from secondary IL nodes to terminal nodes (4 outcomes from PL_C, 4 from PL_D)
        # These should map to the correct keys in terminals
        G.edge("IL2_C", terminals[f"{initial_action_labels[0][0]}{il_action_labels[0][0]}{pl_action_labels[0][0]}{secondary_il_labels[0][0]}"]) # Initial_IL_C_PL_C -> IL2_C
        G.edge("IL2_C", terminals[f"{initial_action_labels[0][0]}{il_action_labels[1][0]}{pl_action_labels[0][0]}{secondary_il_labels[0][0]}"]) # Initial_IL_D_PL_C -> IL2_C
        G.edge("IL2_C", terminals[f"{initial_action_labels[0][0]}{il_action_labels[0][0]}{pl_action_labels[1][0]}{secondary_il_labels[0][0]}"]) # Initial_IL_C_PL_D -> IL2_C
        G.edge("IL2_C", terminals[f"{initial_action_labels[0][0]}{il_action_labels[1][0]}{pl_action_labels[1][0]}{secondary_il_labels[0][0]}"]) # Initial_IL_D_PL_D -> IL2_C

        G.edge("IL2_D", terminals[f"{initial_action_labels[0][0]}{il_action_labels[0][0]}{pl_action_labels[0][0]}{secondary_il_labels[1][0]}"]) # Initial_IL_C_PL_C -> IL2_D
        G.edge("IL2_D", terminals[f"{initial_action_labels[0][0]}{il_action_labels[1][0]}{pl_action_labels[0][0]}{secondary_il_labels[1][0]}"]) # Initial_IL_D_PL_C -> IL2_D
        G.edge("IL2_D", terminals[f"{initial_action_labels[0][0]}{il_action_labels[0][0]}{pl_action_labels[1][0]}{secondary_il_labels[1][0]}"]) # Initial_IL_C_PL_D -> IL2_D
        G.edge("IL2_D", terminals[f"{initial_action_labels[0][0]}{il_action_labels[1][0]}{pl_action_labels[1][0]}{secondary_il_labels[1][0]}"]) # Initial_IL_D_PL_D -> IL2_D

    else:
        # Edges from PL decisions directly to terminal nodes (for 3 actors)
        G.edge("PL_C", terminals[f"{initial_action_labels[0][0]}{il_action_labels[0][0]}{pl_action_labels[0][0]}"]) # Initial_IL_C_PL_C
        G.edge("PL_C", terminals[f"{initial_action_labels[0][0]}{il_action_labels[1][0]}{pl_action_labels[0][0]}"]) # Initial_IL_D_PL_C
        G.edge("PL_D", terminals[f"{initial_action_labels[0][0]}{il_action_labels[0][0]}{pl_action_labels[1][0]}"]) # Initial_IL_C_PL_D
        G.edge("PL_D", terminals[f"{initial_action_labels[0][0]}{il_action_labels[1][0]}{pl_action_labels[1][0]}"]) # Initial_IL_D_PL_D


    # Add title, metrics, and legend
    G.attr(label=f"Sequential Game for {event_name}\nMetrics: Trust={metrics['trust']}, Concession={metrics['concession']}, Escalation={metrics['escalation']}\nPayoffs: (IL, PL) | Scale: 5=Max Gain, 0=Neutral, -5=Max Loss")
    G.attr(fontsize='12')
    G.node("Legend", label="Legend: Green=Cooperate, Yellow=Mixed, Salmon=Defect\nIL=Israel, PL=Palestine/Hamas", shape="plaintext")

    # Render and save the graph
    output_file = G.render(filename=file_name, format='png', cleanup=True)

    # Display the rendered image using matplotlib
    plt.figure(figsize=(12, 8))
    img = plt.imread(output_file)
    plt.imshow(img)
    plt.axis('off')
    plt.title(f"Sequential Game for {event_name}", fontsize=14)
    plt.show()

