# Imports
import pandas as pd
import matplotlib.pyplot as plt
import networkx as nx
from graphviz import Digraph
from IPython.display import Image

# Load dataset (placeholder for conflict_data.csv)
# Assuming conflict_data.csv exists or creating a dummy for execution
try:
    df = pd.read_csv("conflict_data.csv")
except FileNotFoundError:
    print("conflict_data.csv not found. Creating a dummy DataFrame.")
    df = pd.DataFrame({
        'event': ['Camp David Accords', 'Oslo Accords', '2023 Escalation'],
        'date': ['1978-09-17', '1993-09-13', '2023-10-07'],
        'actor1': ['Egypt', 'PLO', 'Hamas'],
        'action1': ['Negotiate', 'Initiate Talks', 'Attack'],
        'actor2': ['Israel', 'Israel', 'Israel'],
        'action2': ['Negotiate', 'Engage', 'Escalate'],
        'actor3': ['US', 'PLO', 'Palestine/Hamas'],
        'action3': ['Mediate', 'Recognize', 'Resist']
    })

# Utility function to build and draw decision tree with refinements
def draw_sequential_game(event_name, initial_actor, initial_action_labels, il_action_labels, pl_action_labels,
                        secondary_il_labels, us_mediation_labels, payoffs, metrics, file_name):
    G = Digraph(format='png', node_attr={'fontsize': '10', 'shape': 'box'}, edge_attr={'arrowsize': '0.8', 'fontsize': '10'})

    # Nodes: Initial actor, IL (Israel), PL (Palestine/Hamas), optional secondary IL and U.S. mediation
    G.node("Initial", label=f"{initial_actor}\n{initial_action_labels[0]}", style="filled", fillcolor="lightcoral")
    G.node("IL", label="IL: Israel\n(First Response)", style="filled", fillcolor="lightblue")
    G.node("PL_C", label="PL: Palestine/Hamas\n(Cooperate)", style="filled", fillcolor="lightgreen")
    G.node("PL_D", label="PL: Palestine/Hamas\n(Defect)", style="filled", fillcolor="lightgreen")

    # Optional secondary IL node for 2023 escalation
    if secondary_il_labels:
        G.node("IL2_C", label="IL: Israel\n(De-escalate)", style="filled", fillcolor="lightblue")
        G.node("IL2_D", label="IL: Israel\n(Retaliate)", style="filled", fillcolor="lightblue")

    # Optional U.S. mediation node for Camp David
    if us_mediation_labels:
        G.node("US_C", label="US: Mediation\n(Accept)", style="filled", fillcolor="lightgray")
        G.node("US_D", label="US: Mediation\n(Reject)", style="filled", fillcolor="lightgray")

    # Terminal nodes for outcomes
    terminals = {}
    outcomes = ['HCC', 'HCD', 'HDC', 'HDD']
    if secondary_il_labels:
        outcomes = [f"{o}_{s}" for o in outcomes for s in ['C', 'D']]
    if us_mediation_labels:
        outcomes = [f"{o}_{u}" for o in outcomes for u in ['USC', 'USD']]

    labels_list = []
    for p in payoffs:
        label = f"({p[0]:.2f}, {p[1]:.2f})"
        if len(p) > 2:
            label += f"\n[{p[2]}]"
        if len(p) > 3:
            label += f"\n[{p[3]}]"
        labels_list.append(label)

    for outcome, label in zip(outcomes, labels_list):
        node = "T_" + outcome
        terminals[outcome] = node
        color = "lightgreen"
        if 'D' in outcome:
            color = "salmon"
        elif 'C' in outcome and 'D' in outcome:
            color = "lightyellow"
        if 'Escalate' in label:
            color = "salmon"
        elif 'Peace effort' in label or 'De-escalate' in label:
            color = "lightgreen"
        G.node(node, label=label, style="filled", fillcolor=color, shape="circle")

    # Edges reflecting historical sequence - Base Edges
    G.edge("Initial", "IL", label=f"{initial_actor} Initiates")
    G.edge("IL", "PL_C", label=il_action_labels[0])
    G.edge("IL", "PL_D", label=il_action_labels[1])

    # Connecting PL nodes to the next stage (either terminals or optional nodes)
    if secondary_il_labels:
        G.edge("PL_C", "IL2_C", label=pl_action_labels[0])
        G.edge("PL_C", "IL2_D", label=pl_action_labels[0])
        G.edge("PL_D", "IL2_C", label=pl_action_labels[1])
        G.edge("PL_D", "IL2_D", label=pl_action_labels[1])
        for outcome in ['HCC', 'HCD', 'HDC', 'HDD']:
            if f"{outcome}_C" in terminals:
                G.edge("IL2_C", terminals[f"{outcome}_C"], label=secondary_il_labels[0])
            if f"{outcome}_D" in terminals:
                G.edge("IL2_D", terminals[f"{outcome}_D"], label=secondary_il_labels[1])
    elif us_mediation_labels:
        G.edge("PL_C", "US_C", label=pl_action_labels[0])
        G.edge("PL_C", "US_D", label=pl_action_labels[0])
        G.edge("PL_D", "US_C", label=pl_action_labels[1])
        G.edge("PL_D", "US_D", label=pl_action_labels[1])
        for outcome in ['HCC', 'HCD', 'HDC', 'HDD']:
            if f"{outcome}_USC" in terminals:
                G.edge("US_C", terminals[f"{outcome}_USC"], label=us_mediation_labels[0])
            if f"{outcome}_USD" in terminals:
                G.edge("US_D", terminals[f"{outcome}_USD"], label=us_mediation_labels[1])
    else:
        G.edge("PL_C", terminals['HCC'], label=pl_action_labels[0])
        G.edge("PL_C", terminals['HCD'], label=pl_action_labels[1])
        G.edge("PL_D", terminals['HDC'], label=pl_action_labels[0])
        G.edge("PL_D", terminals['HDD'], label=pl_action_labels[1])

    # Add title, metrics, and expanded legend
    trust_adjustment = (10 - metrics['trust']) / 10
    escalation_cost_factor = metrics['escalation'] / 10
    G.attr(label=f"Sequential Game for {event_name}\nMetrics: Trust={metrics['trust']}, Concession={metrics['concession']}, Escalation={metrics['escalation']}\nPayoffs: (IL, PL) | Scale: 5=Max Gain, 0=Neutral, -5=Max Loss\nTrust Decay: Reduce by {(trust_adjustment*100):.0f}%, Escalation Cost: {(escalation_cost_factor*100):.0f}%")
    G.node("Legend", label="Legend: Green=Cooperate, Yellow=Mixed, Red=Escalate\nIL=Israel, PL=Palestine/Hamas\nTrust: 0–10 (higher=better), Escalation: 0–10 (higher=worse)\nLoss Aversion: Losses doubled (e.g., -1 → -2)", shape="plaintext")

    # Render and save the graph
    output_file = G.render(filename=file_name, format='png', cleanup=True)

    # Display the rendered image using matplotlib
    plt.figure(figsize=(12, 8))
    plt.imshow(plt.imread(output_file))
    plt.axis('off')
    plt.title(f"Sequential Game for {event_name}", fontsize=14)
    plt.show()

