import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
from matplotlib.patches import Patch

# Load dataset (placeholder for conflict_data.csv)
try:
    df = pd.read_csv('conflict_data.csv')
except FileNotFoundError:
    print("conflict_data.csv not found. Creating a dummy DataFrame.")
    df = pd.DataFrame({
        'event': ['Camp David Accords', 'Oslo Accords', '2023 Escalation'],
        'date': ['1978-09-17', '1993-09-13', '2023-10-07'],
        'actor1': ['Egypt', 'PLO', 'Hamas'],
        'action1': ['Negotiate', 'Initiate Talks', 'Attack'],
        'actor2': ['Israel', 'Israel', 'Israel'],
        'action2': ['Negotiate', 'Engage', 'Escalate'],
        'actor3': ['US', 'PLO', 'Palestine/Hamas'],
        'action3': ['Mediate', 'Recognize', 'Resist']
    })

# --- Simulation Setup ---
rounds = ['1978', '1993', '2023']
wing_scores = {
    0: {'IL': 0.8, 'PL': -0.4},  # Begin +0.8
    1: {'IL': -0.4, 'PL': -0.6},  # Rabin -0.4
    2: {'IL': 0.6, 'PL': -0.8}    # Netanyahu +0.6
}
initial_trust = 5.0
P_C_IL = 0.5 - 0.3 * wing_scores[0]['IL']
P_C_PL = 0.5 - 0.3 * wing_scores[0]['PL']
bounded_rationality_factor = 0.1
learning_rate = 0.05
misperception_factor = 0.05

# Simulation storage
history = {
    'actions_IL': [], 'actions_PL': [],
    'payoffs_IL': [], 'payoffs_PL': [],
    'trust': [initial_trust], 'Dt': [], 'P_C_IL': [], 'P_C_PL': []
}

# Payoff function
def get_payoff(action_IL, action_PL, mediation=False):
    base_payoffs = {
        ('C', 'C'): (3, 3),
        ('C', 'D'): (0, 5),
        ('D', 'C'): (5, 0),
        ('D', 'D'): (1, 1)
    }
    payoff_IL, payoff_PL = base_payoffs.get((action_IL, action_PL), (1, 1))
    if mediation and action_IL == 'C' and action_PL == 'C':
        payoff_IL, payoff_PL = 4, 4
    return payoff_IL, payoff_PL

# Simulate game
np.random.seed(42)
trust = initial_trust
escalation_levels = [3, 3, 8]
for round_idx in range(len(rounds)):
    P_C_IL = np.clip(P_C_IL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1)
    P_C_PL = np.clip(P_C_PL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception_factor, misperception_factor), 0, 1)
    P_C_IL_noise = np.clip(P_C_IL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    P_C_PL_noise = np.clip(P_C_PL + np.random.uniform(-bounded_rationality_factor, bounded_rationality_factor), 0, 1)
    action_IL = 'C' if np.random.rand() < P_C_IL_noise else 'D'
    action_PL = 'C' if np.random.rand() < P_C_PL_noise else 'D'
    history['actions_IL'].append(action_IL)
    history['actions_PL'].append(action_PL)
    history['P_C_IL'].append(P_C_IL)
    history['P_C_PL'].append(P_C_PL)

    mediation = np.random.rand() < 0.5
    payoff_IL, payoff_PL = get_payoff(action_IL, action_PL, mediation)
    history['payoffs_IL'].append(payoff_IL)
    history['payoffs_PL'].append(payoff_PL)

    if action_IL == 'C' and action_PL == 'C':
        trust = min(10.0, trust + 1)
    elif action_IL == 'D' and action_PL == 'D':
        trust = max(0.0, trust - 2)
    else:
        trust = max(0.0, trust - 1)
    history['trust'].append(trust)

    # Compute Dt
    concession_size = 1.0 if action_IL == 'C' and action_PL == 'C' else 0.5 if action_IL == 'C' or action_PL == 'C' else 0.1
    Dt = 0.5 * trust * concession_size
    history['Dt'].append(Dt)

# --- Visualization ---
fig = plt.figure(figsize=(12, 10))
gs = fig.add_gridspec(2, 2, width_ratios=[3, 1], height_ratios=[2, 1], hspace=0.3, wspace=0.3)

# 1. Stage-Based Payoff Heatmap
ax1 = fig.add_subplot(gs[0, 0])
payoff_matrix = np.array([history['payoffs_IL'], history['payoffs_PL']])
P_C_matrix = np.array([history['P_C_IL'], history['P_C_PL']])
Dt_values = history['Dt']
trust_values = history['trust'][1:]
trust_decay = [(1 - t/10) * 100 for t in trust_values]
escalation_cost = [e * 10 for e in escalation_levels]

sns.heatmap(payoff_matrix, annot=True, fmt='.2f', cmap='RdYlGn', cbar=True, ax=ax1,
            xticklabels=rounds, yticklabels=['IL', 'PL'],
            vmin=-5, vmax=5, center=0,
            cbar_kws={'label': 'Payoff'},
            linewidths=0.5, linecolor='gray')

# Annotate P_C, Dt, trust, etc.
for i in range(len(rounds)):
    for j in range(2):
        P_C = P_C_matrix[j, i]
        ax1.text(i + 0.5, j + 0.2, f'P_C: {P_C:.2f}', ha='center', va='center', fontsize=8)
        if j == 0:
            ax1.text(i + 0.5, 1.8, f'D_t: {Dt_values[i]:.2f}', ha='center', va='top', fontsize=8)
    ax1.text(i + 0.5, -0.3, f'T: {trust_values[i]:.1f}, D: {trust_decay[i]:.0f}%, E: {escalation_cost[i]:.0f}%',
             ha='center', va='top', fontsize=8)

# Ideological scores
ax1.text(0.5, -0.8, 'Begin +0.8', ha='center', fontsize=8)
ax1.text(1.5, -0.8, 'Rabin -0.4', ha='center', fontsize=8)
ax1.text(2.5, -0.8, 'Netanyahu +0.6', ha='center', fontsize=8)

ax1.set_title('Repeated Game Payoff Trends (1978–2023)', fontsize=12, pad=10)
ax1.set_ylabel('Actor', fontsize=10)
ax1.set_xlabel('Stage', fontsize=10)
plt.xticks(rotation=45, ha='right', fontsize=9)
plt.yticks(fontsize=9)

# Legend
legend_elements = [
    Patch(facecolor='green', label='Cooperate (Payoff > 1)'),
    Patch(facecolor='yellow', label='Mixed (0 to 1)'),
    Patch(facecolor='red', label='Escalate (< 0)'),
    Patch(facecolor='white', edgecolor='black', label='T: Trust (0–10), D: Decay %, E: Cost %'),
    Patch(facecolor='white', edgecolor='black', label='Loss Aversion: Losses doubled'),
    Patch(facecolor='white', edgecolor='black', label='D_t: Trade restoration (SDG 8)')
]
ax1.legend(handles=legend_elements, fontsize=8, loc='upper center', bbox_to_anchor=(0.5, -0.3), ncol=2)

# 2. Line Graph for Dt and Avg P_C
ax2 = fig.add_subplot(gs[0, 1])
avg_P_C = [(p1 + p2) / 2 for p1, p2 in zip(history['P_C_IL'], history['P_C_PL'])]
ax2.plot(rounds, Dt_values, '-o', color='purple', label='D_t', linewidth=1.5, markersize=5)
ax2.set_ylabel('D_t (Development)', fontsize=10, color='purple')
ax2.tick_params(axis='y', labelcolor='purple')
ax2.set_ylim(0, max(Dt_values) * 1.2)
ax2.grid(True, linestyle='--', alpha=0.5)

ax3 = ax2.twinx()
ax3.plot(rounds, avg_P_C, '-s', color='blue', label='Avg P_C', linewidth=1.5, markersize=5)
ax3.set_ylabel('Avg P_C', fontsize=10, color='blue')
ax3.tick_params(axis='y', labelcolor='blue')
ax3.set_ylim(0, 1)

ax2.set_title('D_t and P_C Trends', fontsize=10)
ax2.set_xticks(range(len(rounds)))
ax2.set_xticklabels(rounds, rotation=45, ha='right', fontsize=9)
lines1, labels1 = ax2.get_legend_handles_labels()
lines2, labels2 = ax3.get_legend_handles_labels()
ax2.legend(lines1 + lines2, labels1 + labels2, fontsize=8, loc='upper right')

# 3. Power Asymmetry Inset
ax4 = fig.add_subplot(gs[1, :])
payoff_asymmetry = {'IL (D, C)': 5, 'PL (D, C)': 0}
actors = list(payoff_asymmetry.keys())
values = list(payoff_asymmetry.values())
bars = ax4.bar(actors, values, color=['#1F77B4', '#2CA02C'], width=0.4)
ax4.bar_label(bars, labels=[f'{v}' for v in values], label_type='edge', fontsize=8)
ax4.set_title('Power Asymmetry (D, C)', fontsize=10)
ax4.set_ylabel('Payoff', fontsize=9)
ax4.set_ylim(0, 6)
ax4.tick_params(axis='x', labelsize=9)
ax4.tick_params(axis='y', labelsize=9)

# Save and show
plt.tight_layout()
plt.savefig('repeated_game_visuals_refined.png', dpi=300, bbox_inches='tight')
plt.show()

import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np

# Setup visual style
sns.set(style="whitegrid", font_scale=1.1)
plt.rcParams['figure.autolayout'] = True

# Dummy data if CSV not found
try:
    df = pd.read_csv('conflict_data.csv')
except FileNotFoundError:
    df = pd.DataFrame({
        'event': ['Camp David Accords', 'Oslo Accords', '2023 Escalation'],
        'date': ['1978-09-17', '1993-09-13', '2023-10-07'],
        'actor1': ['Egypt', 'PLO', 'Hamas'],
        'action1': ['Negotiate', 'Initiate Talks', 'Attack'],
        'actor2': ['Israel', 'Israel', 'Israel'],
        'action2': ['Negotiate', 'Engage', 'Escalate'],
        'actor3': ['US', 'PLO', 'Palestine/Hamas'],
        'action3': ['Mediate', 'Recognize', 'Resist']
    })

# --- Simulation Setup ---
rounds = ['1978', '1993', '2023']
wing_scores = {
    0: {'IL': 0.8, 'PL': -0.4},
    1: {'IL': -0.4, 'PL': -0.6},
    2: {'IL': 0.6, 'PL': -0.8}
}
initial_trust = 5.0
P_C_IL = 0.5 - 0.3 * wing_scores[0]['IL']
P_C_PL = 0.5 - 0.3 * wing_scores[0]['PL']
learning_rate = 0.05
bounded_rationality = 0.1
misperception = 0.05
escalation_levels = [3, 3, 8]

# History tracking
history = {
    'actions_IL': [], 'actions_PL': [],
    'payoffs_IL': [], 'payoffs_PL': [],
    'trust': [initial_trust], 'Dt': [], 'P_C_IL': [], 'P_C_PL': []
}

# Payoff function
def get_payoff(a_IL, a_PL, mediation=False):
    matrix = {('C', 'C'): (3, 3), ('C', 'D'): (0, 5), ('D', 'C'): (5, 0), ('D', 'D'): (1, 1)}
    il, pl = matrix.get((a_IL, a_PL), (1, 1))
    if mediation and a_IL == 'C' and a_PL == 'C':
        return 4, 4
    return il, pl

# Game Simulation
np.random.seed(42)
trust = initial_trust
for i in range(len(rounds)):
    # Adjust cooperation probabilities
    P_C_IL = np.clip(P_C_IL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception, misperception), 0, 1)
    P_C_PL = np.clip(P_C_PL + learning_rate * (trust / 10 - 0.5) + np.random.uniform(-misperception, misperception), 0, 1)

    # Add bounded rationality noise
    noisy_IL = np.clip(P_C_IL + np.random.uniform(-bounded_rationality, bounded_rationality), 0, 1)
    noisy_PL = np.clip(P_C_PL + np.random.uniform(-bounded_rationality, bounded_rationality), 0, 1)

    # Decide actions
    action_IL = 'C' if np.random.rand() < noisy_IL else 'D'
    action_PL = 'C' if np.random.rand() < noisy_PL else 'D'
    mediation = np.random.rand() < 0.5

    # Compute payoff and update trust
    payoff_IL, payoff_PL = get_payoff(action_IL, action_PL, mediation)
    trust += 1 if action_IL == 'C' and action_PL == 'C' else -2 if action_IL == 'D' and action_PL == 'D' else -1
    trust = np.clip(trust, 0, 10)

    # Calculate D_t
    if action_IL == 'C' and action_PL == 'C':
        D_t = 0.5 * trust * 1.0
    elif action_IL == 'C' or action_PL == 'C':
        D_t = 0.5 * trust * 0.5
    else:
        D_t = 0.5 * trust * 0.1

    # Log history
    history['actions_IL'].append(action_IL)
    history['actions_PL'].append(action_PL)
    history['payoffs_IL'].append(payoff_IL)
    history['payoffs_PL'].append(payoff_PL)
    history['trust'].append(trust)
    history['Dt'].append(D_t)
    history['P_C_IL'].append(P_C_IL)
    history['P_C_PL'].append(P_C_PL)

# --- Visualizations ---

# 1. Payoff Heatmap
plt.figure(figsize=(8, 3))
payoff_matrix = np.array([history['payoffs_IL'], history['payoffs_PL']])
sns.heatmap(payoff_matrix, annot=True, cmap="RdYlGn", linewidths=.5,
            xticklabels=rounds, yticklabels=['IL', 'PL'], cbar_kws={'label': 'Payoff'})
plt.title('Payoffs Over Time')
plt.xlabel('Round')
plt.ylabel('Actor')
plt.tight_layout()
plt.savefig('payoff_heatmap.png', dpi=300)
plt.show()

# 2. Trust and Cooperation Over Time
plt.figure(figsize=(8, 4))
avg_P_C = np.array(history['P_C_IL']) + np.array(history['P_C_PL']) / 2
plt.plot(rounds, history['trust'][1:], marker='o', label='Trust', color='darkgreen')
plt.plot(rounds, avg_P_C, marker='s', label='Avg P_C', color='royalblue')
plt.title("Trust & Cooperation Probability")
plt.ylabel("Value")
plt.xlabel("Round")
plt.legend()
plt.grid(True, linestyle='--', alpha=0.6)
plt.tight_layout()
plt.savefig('trust_cooperation_trend.png', dpi=300)
plt.show()

# 3. Developmental Trade Restoration (D_t)
plt.figure(figsize=(8, 3))
plt.bar(rounds, history['Dt'], color='mediumpurple')
plt.title("Developmental Trade Restoration (D_t)")
plt.ylabel("D_t Value")
plt.xlabel("Round")
plt.grid(True, axis='y', linestyle='--', alpha=0.6)
plt.tight_layout()
plt.savefig('dt_values.png', dpi=300)
plt.show()

# 4. Power Asymmetry (Last Round D,C)
plt.figure(figsize=(4, 3))
asym = {'IL (D,C)': 5, 'PL (D,C)': 0}
sns.barplot(x=list(asym.keys()), y=list(asym.values()), palette='coolwarm')
plt.title("Power Asymmetry (D,C)")
plt.ylabel("Payoff")
plt.tight_layout()
plt.savefig('power_asymmetry.png', dpi=300)
plt.show()

