# Sequential game visualizer
def draw_sequential_game(
    event_name, initial_actor, initial_action_labels, il_action_labels,
    pl_action_labels, secondary_il_labels, us_mediation_labels,
    payoffs, metrics, file_name
):
    G = Digraph(format='png', node_attr={'fontsize': '10', 'shape': 'box'}, edge_attr={'fontsize': '9', 'arrowsize': '0.6'})

    # Nodes
    G.node("Start", f"{initial_actor}\n{initial_action_labels[0]}", style="filled", fillcolor="lightcoral")
    G.node("IL", "Israel\n(Responds)", style="filled", fillcolor="lightblue")
    G.node("PL_C", "Palestine\n(Cooperate)", style="filled", fillcolor="lightgreen")
    G.node("PL_D", "Palestine\n(Defect)", style="filled", fillcolor="salmon")

    terminal_nodes = []
    for i, (il_payoff, pl_payoff) in enumerate(payoffs):
        label = f"({il_payoff:.2f}, {pl_payoff:.2f})"
        node_name = f"T{i}"
        terminal_nodes.append(node_name)
        color = "lightgreen" if il_payoff >= 2 and pl_payoff >= 2 else "lightyellow" if il_payoff >= 1 else "lightcoral"
        G.node(node_name, label, shape="ellipse", style="filled", fillcolor=color)

    # Edges
    G.edge("Start", "IL", label=f"{initial_actor} Acts")
    G.edge("IL", "PL_C", label=il_action_labels[0])
    G.edge("IL", "PL_D", label=il_action_labels[1])
    G.edge("PL_C", terminal_nodes[0], label=pl_action_labels[0])
    G.edge("PL_C", terminal_nodes[1], label=pl_action_labels[1])
    G.edge("PL_D", terminal_nodes[2], label=pl_action_labels[0])
    G.edge("PL_D", terminal_nodes[3], label=pl_action_labels[1])

    # Annotations
    G.attr(label=f"{event_name}\nTrust: {metrics['trust']}, Escalation: {metrics['escalation']}, Concession: {metrics['concession']}")
    G.node("Legend", "Legend:\n(IL payoff, PL payoff)", shape="note")

    # Render
    output_path = os.path.join(output_dir, file_name)
    G.render(output_path, cleanup=True)
    print(f"[✔] Graph saved to: {output_path}.png")

