    # escalation_cost_factor = metrics['escalation'] / 10 # This variable was defined but not used in the graph drawing logic

    G.attr(label=f"Sequential Game for {event_name}\nMetrics: Trust={metrics['trust']}, Concession={metrics['concession']}, Escalation={metrics['escalation']}")
    G.node("Legend", label="Legend: Green=Cooperate, Yellow=Mixed, Red=Escalate\nTrust: 0–10 | Escalation: 0–10", shape="plaintext") # Removed "Losses doubled" as it's not reflected in the graph drawing

    # Render, save, and display
    output_file = G.render(filename=os.path.join(output_dir, file_name), format='png', cleanup=True)
    print(f"Decision tree for {event_name} saved to: {output_file}")
    display(Image(output_file))  # ✅ Display inline in Colab


