import pandas as pd
from graphviz import Digraph
import os
from IPython.display import Image, display

# Ensure output directory exists
output_dir = "output"
if not os.path.exists(output_dir):
    os.makedirs(output_dir)
print(f"[✔] Output directory ready at: {os.path.abspath(output_dir)}")

# Load dataset (create dummy if not present)
try:
    df = pd.read_csv("conflict_data.csv")
except FileNotFoundError:
    print("conflict_data.csv not found. Creating a dummy DataFrame.")
    df = pd.DataFrame({
        'event': ['Camp David Accords', 'Oslo Accords', '2023 Escalation'],
        'date': ['1978-09-17', '1993-09-13', '2023-10-07'],
        'actor1': ['Egypt', 'PLO', 'Hamas'],
        'action1': ['Negotiate', 'Initiate Talks', 'Attack'],
        'actor2': ['Israel', 'Israel', 'Israel'],
        'action2': ['Negotiate', 'Engage', 'Escalate'],
        'actor3': ['US', 'PLO', 'Palestine/Hamas'],
        'action3': ['Mediate', 'Recognize', 'Resist']
    })

# Utility function to build and draw decision tree
def draw_sequential_game(event_name, initial_actor, initial_action_labels, il_action_labels, pl_action_labels,
                        secondary_il_labels, us_mediation_labels, payoffs, metrics, file_name):
    G = Digraph(format='png', node_attr={'fontsize': '10', 'shape': 'box'}, edge_attr={'arrowsize': '0.8', 'fontsize': '10'})

    G.node("Initial", label=f"{initial_actor}\n{initial_action_labels[0]}", style="filled", fillcolor="lightcoral")
    G.node("IL", label="IL: Israel\n(First Response)", style="filled", fillcolor="lightblue")
    G.node("PL_C", label="PL: Palestine\n(Cooperate)", style="filled", fillcolor="lightgreen")
    G.node("PL_D", label="PL: Palestine\n(Defect)", style="filled", fillcolor="lightgreen")

    if secondary_il_labels:
        G.node("IL2_C", label="IL: Israel\n(De-escalate)", style="filled", fillcolor="lightblue")
        G.node("IL2_D", label="IL: Israel\n(Retaliate)", style="filled", fillcolor="lightblue")

    if us_mediation_labels:
        G.node("US_C", label="US: Mediation\n(Accept)", style="filled", fillcolor="lightgray")
        G.node("US_D", label="US: Mediation\n(Reject)", style="filled", fillcolor="lightgray")

    # Terminal nodes
    terminals = {}
    outcomes = ['HCC', 'HCD', 'HDC', 'HDD']
    if secondary_il_labels:
        outcomes = [f"{o}_{s}" for o in outcomes for s in ['C', 'D']]
    if us_mediation_labels:
        outcomes = [f"{o}_{u}" for o in outcomes for u in ['USC', 'USD']]

    # Validate payoff length
    expected_len = len(outcomes)
    if len(payoffs) != expected_len:
        raise ValueError(f"Number of payoffs ({len(payoffs)}) does not match expected number of outcomes ({expected_len}) for {event_name}.")

    # Apply loss aversion (double negative values)
    adjusted_payoffs = []
    for p in payoffs:
        il_payoff, pl_payoff = p
        il_payoff = -2 * il_payoff if il_payoff < 0 else il_payoff
        pl_payoff = -2 * pl_payoff if pl_payoff < 0 else pl_payoff
        adjusted_payoffs.append((il_payoff, pl_payoff))
    labels_list = [f"({p[0]:.2f}, {p[1]:.2f})" for p in adjusted_payoffs]

    for i, outcome in enumerate(outcomes):
        node = "T_" + outcome
        terminals[outcome] = node
        color = "lightgreen"
        if 'D' in outcome:
            color = "salmon"
        elif 'C' in outcome and 'D' in outcome:
            color = "lightyellow"
        G.node(node, label=labels_list[i], style="filled", fillcolor=color, shape="circle")

    G.edge("Initial", "IL", label=f"{initial_actor} Initiates")
    G.edge("IL", "PL_C", label=il_action_labels[0])
    G.edge("IL", "PL_D", label=il_action_labels[1])

    if secondary_il_labels:
        G.edge("PL_C", "IL2_C", label=pl_action_labels[0])  # PL Cooperate → IL De-escalate
        G.edge("PL_D", "IL2_D", label=pl_action_labels[1])  # PL Defect → IL Retaliate
        for o in ['HCC', 'HCD', 'HDC', 'HDD']:
            if f"{o}_C" in terminals:
                G.edge("IL2_C", terminals[f"{o}_C"], label=secondary_il_labels[0])
            if f"{o}_D" in terminals:
                G.edge("IL2_D", terminals[f"{o}_D"], label=secondary_il_labels[1])
    elif us_mediation_labels:
        G.edge("PL_C", "US_C", label=pl_action_labels[0])
        G.edge("PL_C", "US_D", label=pl_action_labels[0])
        G.edge("PL_D", "US_C", label=pl_action_labels[1])
        G.edge("PL_D", "US_D", label=pl_action_labels[1])
        for o in ['HCC', 'HCD', 'HDC', 'HDD']:
            if f"{o}_USC" in terminals:
                G.edge("US_C", terminals[f"{o}_USC"], label=us_mediation_labels[0])
            if f"{o}_USD" in terminals:
                G.edge("US_D", terminals[f"{o}_USD"], label=us_mediation_labels[1])
    else:
        G.edge("PL_C", terminals['HCC'], label=pl_action_labels[0])
        G.edge("PL_C", terminals['HCD'], label=pl_action_labels[1])
        G.edge("PL_D", terminals['HDC'], label=pl_action_labels[0])
        G.edge("PL_D", terminals['HDD'], label=pl_action_labels[1])

    trust_adjustment = (10 - metrics['trust']) / 10
    escalation_cost_factor = metrics['escalation'] / 10
    G.attr(label=f"Sequential Game for {event_name}\nMetrics: Trust={metrics['trust']}, Concession={metrics['concession']}, Escalation={metrics['escalation']}\nTrust Decay: {(trust_adjustment*100):.0f}%, Escalation Cost: {(escalation_cost_factor*100):.0f}%")
    G.node("Legend", label="Legend: Green=Cooperate, Yellow=Mixed, Red=Escalate\nTrust: 0–10 | Escalation: 0–10\nLoss Aversion: Losses doubled", shape="plaintext")

    output_file = G.render(filename=os.path.join(output_dir, file_name), format='png', cleanup=True)
    print(f"Decision tree for {event_name} saved to: {output_file}")
    display(Image(output_file))

